            a.IS_USE, 
            NULL AS descr
      FROM dbo.TH_MST_SALES_PRODUCT_MAP_CAL  AS a
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_SALES_PRODUCT_MAP_CAL', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_OP_RES_GROUP
           (
            MASTER_ID, 
            PLAN_ID, 
            SITE_ID, 
            ROUTE_ID, 
            OPERATION_ID, 
            ITEM_ID, 
            RESOURCE_MAP_ID, 
            RESOURCE_MAP_LEVEL, 
            MIN_TACT_TIME, 
            AVG_TACT_TIME, 
            MAX_TACT_TIME, 
            TACT_TIME_UOM, 
            YIELD, 
            RESOURCE_SELECTOR_ID, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            a.ITEM_ID, 
            RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                    +'_'+ISNULL(a.SITE_ID, '')
                    +'_'+ISNULL(a.ROUTE_ID, '')
                    +'_'+ISNULL(a.OPERATION_ID, ''))) AS resource_map_id, 
            1 AS resource_map_level, 
            case when min(a.TACT_TIME) = 0 then avg(a.TACT_TIME) else min(a.TACT_TIME) end AS min_tact_time, 
            case when min(a.TACT_TIME) = 0 then avg(a.TACT_TIME) else min(a.TACT_TIME) end AS avg_tact_time, 
            case when min(a.TACT_TIME) = 0 then avg(a.TACT_TIME) else min(a.TACT_TIME) end AS max_tact_time, 
            --min(a.TACT_TIME) AS min_tact_time, 
            --avg(a.TACT_TIME) AS avg_tact_time, 
            --max(a.TACT_TIME) AS max_tact_time, 
            max(a.TACT_TIME_UOM) AS tact_time_uom, 
            max(a.YIELD) AS yield, 
            NULL AS resource_selector_id, 
            NULL AS descr
      FROM  dbo.TH_MST_OP_RESOURCE  AS a
            INNER JOIN dbo.TH_MST_ITEM_ROUTE_SITE  AS b
                  ON    a.MASTER_ID = b.MASTER_ID 
                  AND   a.PLAN_ID = b.PLAN_ID 
                  AND   a.ITEM_ID = b.ITEM_ID 
                  AND   a.SITE_ID = b.SITE_ID 
                  AND   a.ROUTE_ID = b.ROUTE_ID 
                  AND   a.OPERATION_ID = b.OPERATION_ID 
                  AND   isnull(b.IS_VALID, 'Y') = 'Y' 
            INNER JOIN dbo.TH_MST_RESOURCE  AS c
                  ON    a.MASTER_ID = c.MASTER_ID 
                  AND   a.PLAN_ID = c.PLAN_ID 
                  AND   a.RESOURCE_ID = c.RESOURCE_ID 
                  AND   c.RESOURCE_TYPE = 'MAIN' 
                  AND   isnull(c.IS_VALID, 'Y') = 'Y' 
                  AND   isnull(c.IS_EXCEPTION, 'N') = 'N'
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id 
      AND   isnull(a.IS_VALID, 'Y') = 'Y' 
      GROUP BY 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            a.ITEM_ID, 
            RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                    +'_'+ISNULL(a.SITE_ID, '')
                    +'_'+ISNULL(a.ROUTE_ID, '')
                    +'_'+ISNULL(a.OPERATION_ID, '')))
      UNION ALL
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            a.ITEM_ID, 
            RTRIM(LTRIM(ISNULL(CAST(a.resource_map_id AS nvarchar(max)), '') 
               + '::' + ISNULL(CAST(a.resource_map_level AS nvarchar(max)), ''))) AS resource_map_id, 
            a.resource_map_level, 
            a.min_tact_time, 
            a.avg_tact_time, 
            a.max_tact_time, 
            a.tact_time_uom, 
            a.yield, 
            NULL AS resource_selector_id, 
            NULL AS descr
      FROM 
           (
            SELECT 
                  a.MASTER_ID, 
                  a.PLAN_ID, 
                  a.SITE_ID, 
                  a.ROUTE_ID, 
                  a.OPERATION_ID, 
                  a.ITEM_ID, 
                  a.resource_map_id AS resource_map_id, 
                  a.alt_id, 
                  CAST(rank() OVER(PARTITION BY a.resource_map_id
                                   ORDER BY a.alt_id) AS float(53)) + 1 AS resource_map_level, 
                  a.min_tact_time AS min_tact_time, 
                  a.avg_tact_time AS avg_tact_time, 
                  a.max_tact_time AS max_tact_time, 
                  a.tact_time_uom AS tact_time_uom, 
                  a.yield AS yield
            FROM 
                 (
                  SELECT 
                        a.MASTER_ID, 
                        a.PLAN_ID, 
                        a.SITE_ID, 
                        a.ROUTE_ID, 
                        a.OPERATION_ID, 
                        a.ITEM_ID, 
                        isnull(RTRIM(LTRIM(a.ALT_ID)), 'SUB') AS alt_id, 
                        RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                                +'_'+ISNULL(a.SITE_ID, '')
                                +'_'+ISNULL(a.ROUTE_ID, '')
                                +'_'+ISNULL(a.OPERATION_ID, '')
                                +'_'+ISNULL(a.RESOURCE_ID, ''))) AS resource_map_id, 
                        min(a.TACT_TIME) AS min_tact_time, 
                        avg(a.TACT_TIME) AS avg_tact_time, 
                        max(a.TACT_TIME) AS max_tact_time, 
                        max(a.TACT_TIME_UOM) AS tact_time_uom, 
                        max(b.YIELD) AS yield
                  FROM  dbo.TH_MST_SUB_OP_RESOURCE  AS a
                        INNER JOIN dbo.TH_MST_OP_RESOURCE  AS b
                              ON  a.MASTER_ID = b.MASTER_ID 
                              AND a.PLAN_ID = b.PLAN_ID 
                              AND a.SITE_ID = b.SITE_ID 
                              AND a.OPERATION_ID = b.OPERATION_ID 
                              AND a.ITEM_ID = b.ITEM_ID 
                              AND a.RESOURCE_ID = b.RESOURCE_ID 
                              AND isnull(b.IS_VALID, 'Y') = 'Y'
                        INNER JOIN dbo.TH_MST_RESOURCE  AS c
                              ON  a.MASTER_ID = c.MASTER_ID 
                              AND a.PLAN_ID = c.PLAN_ID 
                              AND a.SUB_RESOURCE_ID = c.RESOURCE_ID 
                              AND isnull(c.IS_VALID, 'Y') = 'Y' 
                              AND isnull(c.IS_EXCEPTION, 'N') = 'N' 
                              AND c.RESOURCE_TYPE = 'SUB'
                  WHERE a.MASTER_ID = @v_master_id 
                  AND   a.PLAN_ID = @v_plan_id 
                  AND   isnull(a.IS_VALID, 'Y') = 'Y' 
                  GROUP BY 
                        a.MASTER_ID, 
                        a.PLAN_ID, 
                        a.SITE_ID, 
                        a.ROUTE_ID, 
                        a.OPERATION_ID, 
                        a.ITEM_ID, 
                        isnull(RTRIM(LTRIM(a.ALT_ID)), 'SUB'), 
                        RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                                +'_'+ISNULL(a.SITE_ID, '')
                                +'_'+ISNULL(a.ROUTE_ID, '')
                                +'_'+ISNULL(a.OPERATION_ID, '')
                                +'_'+ISNULL(a.RESOURCE_ID, ''))) 
                     )  AS a
               )  AS a

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_OP_RES_GROUP', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_OP_RES_GROUP_CAL
           (
            MASTER_ID, 
            PLAN_ID, 
            SITE_ID, 
            ROUTE_ID, 
            OPERATION_ID, 
            ITEM_ID, 
            RESOURCE_MAP_ID, 
            START_DTTM, 
            END_DTTM, 
            YIELD, 
            RESOURCE_SELECTOR_ID, 
            IS_USE, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            a.ITEM_ID, 
            RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                    +'_'+ISNULL(a.SITE_ID, '')
                    +'_'+ISNULL(a.ROUTE_ID, '')
                    +'_'+ISNULL(a.OPERATION_ID, ''))) AS resource_map_id, 
            a.START_DATE AS start_dttm, 
            MIN(a.END_DATE) AS end_dttm, 
            max(a.YIELD) AS yield, 
            NULL AS resource_selector_id, 
            max(a.IS_USE) AS is_use, 
            NULL AS descr
      FROM  dbo.TH_MST_OP_RESOURCE_CAL  AS a
            INNER JOIN dbo.TH_MST_ITEM_ROUTE_SITE  AS b
                  ON  a.MASTER_ID = b.MASTER_ID 
                  AND a.PLAN_ID = b.PLAN_ID 
                  AND a.ITEM_ID = b.ITEM_ID 
                  AND a.SITE_ID = b.SITE_ID 
                  AND a.ROUTE_ID = b.ROUTE_ID 
                  AND a.OPERATION_ID = b.OPERATION_ID 
                  AND isnull(b.IS_VALID, 'Y') = 'Y' 
            INNER JOIN dbo.TH_MST_RESOURCE  AS c
                  ON  a.MASTER_ID = c.MASTER_ID 
                  AND a.PLAN_ID = c.PLAN_ID 
                  AND a.RESOURCE_ID = c.RESOURCE_ID 
                  AND c.RESOURCE_TYPE = 'MAIN' 
                  AND isnull(c.IS_VALID, 'Y') = 'Y'
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id
      GROUP BY 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            a.ITEM_ID, 
            RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                    +'_'+ISNULL(a.SITE_ID, '')
                    +'_'+ISNULL(a.ROUTE_ID, '')
                    +'_'+ISNULL(a.OPERATION_ID, ''))) ,
            a.START_DATE
      UNION ALL
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            a.ITEM_ID, 
            b.resource_map_id, 
            a.START_DATE AS start_dttm, 
            MIN(a.END_DATE) AS end_dttm, 
            max(b.yield) AS yield, 
            NULL AS resource_selector_id, 
            max(a.IS_USE) AS is_use, 
            NULL AS descr
      FROM  dbo.TH_MST_SUB_OP_RESOURCE_CAL  AS a, 
          (
            SELECT 
                  a.SITE_ID, 
                  a.ROUTE_ID, 
                  a.OPERATION_ID, 
                  a.ITEM_ID, 
                  a.RESOURCE_ID, 
                  a.ALT_ID, 
                  RTRIM(LTRIM(ISNULL(CAST(a.resource_map_id AS nvarchar(max)), '') 
                     + '::' + ISNULL(CAST(a.resource_map_level AS nvarchar(max)), ''))) AS resource_map_id, 
                  a.resource_map_level, 
                  a.min_tact_time, 
                  a.avg_tact_time, 
                  a.max_tact_time, 
                  a.TACT_TIME_UOM, 
                  a.yield AS yield, 
                  NULL AS resource_selector_id, 
                  NULL AS descr
            FROM 
                (
                  SELECT 
                        a.SITE_ID, 
                        a.ROUTE_ID, 
                        a.OPERATION_ID, 
                        a.ITEM_ID, 
                        a.resource_map_id AS resource_map_id, 
                        a.RESOURCE_ID, 
                        a.alt_id, 
                        CAST(rank() OVER(PARTITION BY a.resource_map_id
                                         ORDER BY a.alt_id) AS float(53)) + 1 AS resource_map_level, 
                        a.min_tact_time AS min_tact_time, 
                        a.avg_tact_time AS avg_tact_time, 
                        a.max_tact_time AS max_tact_time, 
                        a.tact_time_uom, 
                        a.yield AS yield
                  FROM 
                      (
                        SELECT 
                              a.SITE_ID, 
                              a.ROUTE_ID, 
                              a.OPERATION_ID, 
                              a.ITEM_ID, 
                              a.RESOURCE_ID, 
                              isnull(RTRIM(LTRIM(a.ALT_ID)), 'SUB') AS alt_id, 
                              RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                                      +'_'+ISNULL(a.SITE_ID, '')
                                      +'_'+ISNULL(a.ROUTE_ID, '')
                                      +'_'+ISNULL(a.OPERATION_ID, '')
                                      +'_'+ISNULL(a.RESOURCE_ID, ''))) AS resource_map_id, 
                              min(a.TACT_TIME) AS min_tact_time, 
                              avg(a.TACT_TIME) AS avg_tact_time, 
                              max(a.TACT_TIME) AS max_tact_time, 
                              max(a.TACT_TIME_UOM) AS tact_time_uom, 
                              max(b.YIELD) AS yield
                        FROM  dbo.TH_MST_SUB_OP_RESOURCE  AS a
                              INNER JOIN dbo.TH_MST_OP_RESOURCE  AS b
                                    ON  a.MASTER_ID = b.MASTER_ID 
                                    AND a.PLAN_ID = b.PLAN_ID 
                                    AND a.SITE_ID = b.SITE_ID 
                                    AND a.OPERATION_ID = b.OPERATION_ID 
                                    AND a.ITEM_ID = b.ITEM_ID 
                                    AND a.RESOURCE_ID = b.RESOURCE_ID 
                                    AND isnull(b.IS_VALID, 'Y') = 'Y' 
                              INNER JOIN dbo.TH_MST_RESOURCE  AS c
                                    ON  a.MASTER_ID = c.MASTER_ID 
                                    AND a.PLAN_ID = c.PLAN_ID 
                                    AND a.SUB_RESOURCE_ID = c.RESOURCE_ID 
                                    AND isnull(c.IS_VALID, 'Y') = 'Y' 
                                    AND c.RESOURCE_TYPE = 'SUB'
                        WHERE a.MASTER_ID = @v_master_id 
                        AND   a.PLAN_ID = @v_plan_id 
                        AND   isnull(a.IS_VALID, 'Y') = 'Y'
                        GROUP BY 
                              a.SITE_ID, 
                              a.ROUTE_ID, 
                              a.OPERATION_ID, 
                              a.ITEM_ID, 
                              a.RESOURCE_ID, 
                              isnull(RTRIM(LTRIM(a.ALT_ID)), 'SUB') ,
                              RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                                      +'_'+ISNULL(a.SITE_ID, '')
                                      +'_'+ISNULL(a.ROUTE_ID, '')
                                      +'_'+ISNULL(a.OPERATION_ID, '')
                                      +'_'+ISNULL(a.RESOURCE_ID, ''))) 
                      ) AS a
                ) AS a
          ) AS b
      WHERE a.ITEM_ID = b.ITEM_ID 
      AND   a.SITE_ID = b.SITE_ID 
      AND   a.OPERATION_ID = b.OPERATION_ID 
      AND   a.RESOURCE_ID = b.RESOURCE_ID 
      AND   isnull(RTRIM(LTRIM(a.ALT_ID)), 'SUB') = b.ALT_ID
      GROUP BY 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            a.ITEM_ID, 
            b.resource_map_id, 
            a.START_DATE

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_OP_RES_GROUP_CAL', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_ITEM_ROUTE_SITE
           (
            MASTER_ID, 
            PLAN_ID, 
            ITEM_ID, 
            SITE_ID, 
            ROUTE_ID, 
            ROUTE_LEVEL, 
            OPERATION_ID, 
            OPERATION_SEQ, 
            FLOW_ID, 
            MIN_TAT, 
            AVG_TAT, 
            MAX_TAT, 
            TAT_UOM, 
            YIELD, 
            MIN_LOT_SIZE, 
            MAX_LOT_SIZE, 
            INCREMENT_LOT_SIZE, 
            IN_MOVING_LOT_SIZE, 
            OUT_MOVING_LOT_SIZE, 
            IN_MOVE_TIME, 
            OUT_MOVE_TIME, 
            MOVE_TIME_UOM, 
            EARLY_PRODUCING_TERM, 
            EARLY_PRODUCING_TERM_UOM, 
            OPERATION_TYPE, 
            BUFFER_TIME, 
            BUFFER_TIME_UOM, 
            DESCR, 
            TRANSFER_BATCH_SIZE
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.ITEM_ID, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.ROUTE_LEVEL, 
            a.OPERATION_ID, 
            a.OPERATION_SEQ, 
            a.FLOW_ID,
            CASE WHEN TAT_TYPE = 'TAT_CAPA' THEN NULL ELSE A.TAT END AS min_tat, 
            CASE WHEN TAT_TYPE = 'TAT_CAPA' THEN NULL ELSE A.TAT END AS avg_tat, 
            CASE WHEN TAT_TYPE = 'TAT_CAPA' THEN NULL ELSE A.TAT END AS max_tat, 
            a.TAT_UOM AS tat_uom, 
            a.YIELD, 
            a.MIN_LOT_SIZE, 
            a.MAX_LOT_SIZE, 
            a.INCREMENT_LOT_SIZE, 
            a.IN_MOVING_LOT_SIZE, 
            a.OUT_MOVING_LOT_SIZE, 
            a.IN_MOVE_TIME, 
            a.OUT_MOVE_TIME, 
            a.MOVE_TIME_UOM, 
            CASE WHEN a.EARLY_PRODUCING_TERM IS NULL  THEN 365
                                                      ELSE a.EARLY_PRODUCING_TERM
            END  AS early_producing_term, 
            a.EARLY_PRODUCING_TERM_UOM, 
            CASE WHEN a.OPERATION_TYPE IS NULL  THEN 'JIT'
                                                ELSE a.OPERATION_TYPE
            END  AS operation_type, 
            --CASE WHEN TAT_TYPE = 'TAT_MOVE' THEN TAT     ELSE a.BUFFER_TIME END AS BUFFER_TIME, 
            --CASE WHEN TAT_TYPE = 'TAT_MOVE' THEN TAT_UOM ELSE a.BUFFER_TIME_UOM END AS BUFFER_TIME_UOM, 
            A.BUFFER_TIME, 
            A.BUFFER_TIME_UOM, 
            NULL AS descr, 
            transfer_batch_size
      FROM  dbo.TH_MST_ITEM_ROUTE_SITE  AS a
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id 
      AND   isnull(a.IS_VALID, 'Y') = 'Y'

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_ITEM_ROUTE_SITE', 'INSERT', @@ROWCOUNT, null, null, null 
       
      UPDATE  SY_FP_PLAN_STATUS_H
      SET     INBOUND_STEP = '2',
              UPDATE_ID = @v_proc_name, 
              UPDATE_TIME = sysdatetime()
      FROM    SY_FP_PLAN_STATUS_H  AS a
      WHERE   a.INSTANCE_ID = @v_master_id 
      AND     a.PLAN_ID = @v_plan_id

      INSERT INTO dbo.TH_ENG_OP_RES_GROUP_MAP
           (
            MASTER_ID, 
            PLAN_ID, 
            SITE_ID, 
            ROUTE_ID, 
            OPERATION_ID, 
            ITEM_ID, 
            RESOURCE_MAP_ID, 
            RESOURCE_GROUP_ID, 
            SUB_RESOURCE_MAP_ID, 
            RESOURCE_MAP_LEVEL, 
            ALT_PRIORITY, 
            TACT_TIME, 
            TACT_TIME_UOM, 
            YIELD, 
            IS_FIRST_SETUP, 
            GOOD_RATE, 
            BATCH_RATE, 
            CONSUME_RES_RATE, 
            DESCR, 
            PREPARE_TIME, 
            PREPARE_TIME_UOM
           )
      SELECT DISTINCT
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            a.ITEM_ID, 
            RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                    +'_'+ISNULL(a.SITE_ID, '')
                    +'_'+ISNULL(a.ROUTE_ID, '')
                    +'_'+ISNULL(a.OPERATION_ID, ''))) AS resource_map_id, 
            isnull(c.RESOURCE_GROUP_ID, c.RESOURCE_ID) AS resource_group_id, 
            d.sub_resource_map_id, 
            1 AS resource_map_level, 
            a.ALT_PRIORITY, 
            CASE WHEN B.TAT_TYPE IN ('TAT_CAPA','TAT_MOVE') THEN 0.0000000001 ELSE a.TACT_TIME END TACT_TIME, 
            CASE WHEN B.TAT_TYPE IN ('TAT_CAPA','TAT_MOVE') THEN 'SECOND'     ELSE a.TACT_TIME_UOM END TACT_TIME_UOM, 
            a.YIELD, 
            a.IS_FIRST_SETUP, 
            NULL AS good_rate, 
            CASE WHEN C.BATCH_TYPE = 'BATCH' THEN 1 ELSE NULL END AS batch_rate, 
            1 AS consume_res_rate, 
            NULL AS descr, 
            CASE WHEN B.TAT_TYPE = 'TAT_CAPA' THEN B.TAT ELSE NULL END AS prepare_time, 
            ISNULL(B.TAT_UOM, 'MINUTE') AS prepare_time_uom
      FROM 
            dbo.TH_MST_OP_RESOURCE  AS a 
            LEFT OUTER JOIN 
                  (
                    SELECT 
                          fci.SITE_ID, 
                          fci.ROUTE_ID, 
                          fci.OPERATION_ID, 
                          fci.ITEM_ID, 
                          fci.RESOURCE_ID, 
                          RTRIM(LTRIM(ISNULL(CAST(fci.resource_map_id AS nvarchar(max)), '') 
                             + '::' + ISNULL(CAST(fci.resource_map_level AS nvarchar(max)), ''))) AS sub_resource_map_id
                    FROM 
                        (
                          SELECT 
                                a.SITE_ID, 
                                a.ROUTE_ID, 
                                a.OPERATION_ID, 
                                a.ITEM_ID, 
                                a.RESOURCE_ID, 
                                a.resource_map_id AS resource_map_id, 
                                a.alt_id, 
                                CAST(rank() OVER( PARTITION BY a.resource_map_id
                                                  ORDER BY a.alt_id) AS float(53)) + 1 AS resource_map_level
                          FROM 
                              (
                                SELECT 
                                      a.SITE_ID, 
                                      a.ROUTE_ID, 
                                      a.OPERATION_ID, 
                                      a.ITEM_ID, 
                                      a.RESOURCE_ID, 
                                      isnull(RTRIM(LTRIM(a.ALT_ID)), 'SUB') AS alt_id, 
                                      RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                                              +'_'+ISNULL(a.SITE_ID, '')
                                              +'_'+ISNULL(a.ROUTE_ID, '')
                                              +'_'+ISNULL(a.OPERATION_ID, '')
                                              +'_'+ISNULL(a.RESOURCE_ID, ''))) AS resource_map_id
                                FROM  dbo.TH_MST_SUB_OP_RESOURCE  AS a
                                      INNER JOIN dbo.TH_MST_RESOURCE  AS b
                                            ON  a.MASTER_ID = b.MASTER_ID 
                                            AND a.SUB_RESOURCE_ID = b.RESOURCE_ID 
                                            AND a.PLAN_ID = b.PLAN_ID 
                                            AND isnull(b.IS_VALID, 'Y') = 'Y' 
                                            AND b.RESOURCE_TYPE = 'SUB'
                                WHERE a.MASTER_ID = @v_master_id 
                                AND   a.PLAN_ID = @v_plan_id 
                                AND   isnull(a.IS_VALID, 'Y') = 'Y'
                                GROUP BY 
                                      a.SITE_ID, 
                                      a.ROUTE_ID, 
                                      a.OPERATION_ID, 
                                      a.ITEM_ID, 
                                      a.RESOURCE_ID, 
                                      isnull(RTRIM(LTRIM(a.ALT_ID)), 'SUB'), 
                                      RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                                              +'_'+ISNULL(a.SITE_ID, '')
                                              +'_'+ISNULL(a.ROUTE_ID, '')
                                              +'_'+ISNULL(a.OPERATION_ID, '')
                                              +'_'+ISNULL(a.RESOURCE_ID, '')))
                              )  AS a
                        )  AS fci
                    WHERE fci.resource_map_level = 2
                  )  AS d 
                  ON  a.SITE_ID = d.SITE_ID 
                  AND a.ITEM_ID = d.ITEM_ID 
                  AND a.ROUTE_ID = d.ROUTE_ID 
                  AND a.OPERATION_ID = d.OPERATION_ID 
                  AND a.RESOURCE_ID = d.RESOURCE_ID
            INNER JOIN dbo.TH_MST_ITEM_ROUTE_SITE  AS b
                  ON  a.MASTER_ID = b.MASTER_ID 
                  AND a.PLAN_ID = b.PLAN_ID 
                  AND a.ITEM_ID = b.ITEM_ID 
                  AND a.SITE_ID = b.SITE_ID 
                  AND a.ROUTE_ID = b.ROUTE_ID 
                  AND a.OPERATION_ID = b.OPERATION_ID 
                  AND isnull(b.IS_VALID, 'Y') = 'Y' 
            INNER JOIN dbo.TH_MST_RESOURCE  AS c
                  ON  a.MASTER_ID = c.MASTER_ID 
                  AND a.PLAN_ID = c.PLAN_ID 
                  AND a.RESOURCE_ID = c.RESOURCE_ID 
                  AND c.RESOURCE_TYPE = 'MAIN' 
                  AND isnull(c.IS_VALID, 'Y') = 'Y'
            WHERE a.MASTER_ID = @v_master_id 
            AND   a.PLAN_ID = @v_plan_id 
            AND   isnull(a.IS_VALID, 'Y') = 'Y' 
            UNION ALL
            SELECT DISTINCT
                  fci.MASTER_ID, 
                  fci.PLAN_ID, 
                  fci.SITE_ID, 
                  fci.ROUTE_ID, 
                  fci.OPERATION_ID, 
                  fci.ITEM_ID, 
                  RTRIM(LTRIM(ISNULL(CAST(fci.resource_map_id AS nvarchar(max)), '')
                     + '::' + ISNULL(CAST(fci.resource_map_level AS nvarchar(max)), ''))) AS resource_map_id, 
                  fci.RESOURCE_GROUP_ID, 
                  CASE CAST(fci.resource_map_level AS float(53)) - 1
                      WHEN fci.alt_cnt THEN NULL
                                       ELSE RTRIM(LTRIM(ISNULL(CAST(fci.resource_map_id AS nvarchar(max)), '')
                                         + '::' + ISNULL(CAST((CAST(fci.resource_map_level AS float(53)) + 1) AS nvarchar(max)), '')))
                  END  AS sub_resource_map_id, 
                  fci.resource_map_level, 
                  fci.ALT_PRIORITY, 
                  fci.TACT_TIME, 
                  fci.TACT_TIME_UOM, 
                  fci.YIELD, 
                  NULL AS is_first_setup, 
                  NULL AS good_rate, 
                  NULL AS batch_rate, 
                  fci.consume_res_rate, 
                  NULL AS descr, 
                  NULL AS prepare_time, 
                  'MINUTE' AS prepare_time_uom
            FROM 
                (
                  SELECT 
                        a.MASTER_ID, 
                        a.PLAN_ID, 
                        a.SITE_ID, 
                        a.ROUTE_ID, 
                        a.OPERATION_ID, 
                        a.ITEM_ID, 
                        a.resource_map_id AS resource_map_id, 
                        a.alt_id, 
                        CAST(rank() OVER(PARTITION BY a.resource_map_id
                                         ORDER BY a.alt_id) AS float(53)) + 1 AS resource_map_level, 
                        count_big(a.alt_id) OVER(PARTITION BY a.resource_map_id) AS alt_cnt, 
                        a.RESOURCE_GROUP_ID, 
                        a.ALT_PRIORITY, 
                        a.TACT_TIME, 
                        a.TACT_TIME_UOM, 
                        a.consume_res_rate AS consume_res_rate, 
                        a.YIELD
                  FROM 
                      (
                        SELECT 
                              a.MASTER_ID, 
                              a.PLAN_ID, 
                              a.SITE_ID, 
                              a.ROUTE_ID, 
                              a.OPERATION_ID, 
                              a.ITEM_ID, 
                              isnull(RTRIM(LTRIM(a.ALT_ID)), 'SUB') AS alt_id, 
                              RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                                      +'_'+ISNULL(a.SITE_ID, '')
                                      +'_'+ISNULL(a.ROUTE_ID, '')
                                      +'_'+ISNULL(a.OPERATION_ID, '')
                                      +'_'+ISNULL(a.RESOURCE_ID, ''))) AS resource_map_id, 
                              c.RESOURCE_GROUP_ID, 
                              a.ALT_PRIORITY, 
                              a.TACT_TIME, 
                              a.TACT_TIME_UOM, 
                              isnull(a.CONSUME_RES_RATE, 1) AS consume_res_rate, 
                              b.YIELD
                        FROM  dbo.TH_MST_SUB_OP_RESOURCE  AS a
                              INNER JOIN dbo.TH_MST_OP_RESOURCE  AS b
                                    ON  a.MASTER_ID = b.MASTER_ID 
                                    AND a.PLAN_ID = b.PLAN_ID 
                                    AND a.SITE_ID = b.SITE_ID 
                                    AND a.OPERATION_ID = b.OPERATION_ID 
                                    AND a.ITEM_ID = b.ITEM_ID 
                                    AND a.RESOURCE_ID = b.RESOURCE_ID 
                                    AND isnull(b.IS_VALID, 'Y') = 'Y' 
                              INNER JOIN dbo.TH_MST_RESOURCE  AS c
                                    ON  a.MASTER_ID = c.MASTER_ID 
                                    AND a.PLAN_ID = c.PLAN_ID 
                                    AND a.SUB_RESOURCE_ID = c.RESOURCE_ID 
                                    AND isnull(c.IS_VALID, 'Y') = 'Y' 
                                    AND c.RESOURCE_TYPE = 'SUB'
                        WHERE a.MASTER_ID = @v_master_id 
                        AND   a.PLAN_ID = @v_plan_id 
                        AND   isnull(a.IS_VALID, 'Y') = 'Y' 
                      ) AS a
                ) AS fci

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_OP_RES_GROUP_MAP', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_OP_RES_GROUP_MAP_CAL
           (
              MASTER_ID
            , PLAN_ID
            , SITE_ID
            , ROUTE_ID
            , OPERATION_ID
            , ITEM_ID
            , RESOURCE_MAP_ID
            , RESOURCE_GROUP_ID
            , START_DTTM
            , END_DTTM
            , SUB_RESOURCE_MAP_ID
            , RESOURCE_MAP_LEVEL
            , ALT_PRIORITY
            , TACT_TIME
            , TACT_TIME_UOM
            , YIELD
            , GOOD_RATE
            , BATCH_RATE
            , IS_USE
            , DESCR
            , CONSUME_RES_RATE
            , PREPARE_TIME
            , PREPARE_TIME_UOM
            )
      SELECT  DISTINCT 
              a.MASTER_ID
            , a.PLAN_ID
            , a.SITE_ID
            , a.ROUTE_ID
            , a.OPERATION_ID
            , a.ITEM_ID
            , RTRIM(LTRIM(ISNULL(a.ITEM_ID, '')+'_'+ISNULL(a.SITE_ID, '')+'_'+ISNULL(a.ROUTE_ID, '')+'_'+ISNULL(a.OPERATION_ID, ''))) AS resource_map_id
            , c.RESOURCE_GROUP_ID AS resource_group_id
            , a.START_DATE AS start_dttm
            , a.END_DATE AS end_dttm
            , d.sub_resource_map_id
            , 1 AS resource_map_level
            , a.ALT_PRIORITY
            , a.TACT_TIME
            ,a.TACT_TIME_UOM
            , a.YIELD AS yield
            , NULL AS good_rate
            , NULL AS batch_rate
            , a.IS_USE AS is_use
            , a.descr
            , NULL AS consume_res_rate
            , NULL AS prepare_time
            , 'HOUR' AS prepare_time_uom
      FROM 
              dbo.TH_MST_OP_RESOURCE_CAL  AS a 
                LEFT OUTER JOIN (
                                  SELECT 
                                          a.SITE_ID
                                        , a.ROUTE_ID
                                        , a.OPERATION_ID
                                        , a.ITEM_ID
                                        , a.RESOURCE_ID
                                        , RTRIM(LTRIM(ISNULL(CAST(a.resource_map_id AS nvarchar(max)), '') + '::' 
                                                    + ISNULL(CAST(a.resource_map_level AS nvarchar(max)), ''))) AS sub_resource_map_id
                                  FROM 
                                        (
                                          SELECT 
                                                  a.SITE_ID
                                                , a.ROUTE_ID
                                                , a.OPERATION_ID
                                                , a.ITEM_ID
                                                , a.RESOURCE_ID
                                                , a.resource_map_id AS resource_map_id
                                                , a.alt_id
                                                , CAST(rank() OVER (PARTITION BY a.resource_map_id
                                                                    ORDER BY a.alt_id) AS float(53)) + 1 AS resource_map_level
                                          FROM 
                                                (
                                                  SELECT 
                                                          a.SITE_ID
                                                        , a.ROUTE_ID
                                                        , a.OPERATION_ID
                                                        , a.ITEM_ID
                                                        , a.RESOURCE_ID
                                                        , isnull(RTRIM(LTRIM(a.ALT_ID)), 'SUB') AS alt_id
                                                        , RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                                                                  +'_'+ISNULL(a.SITE_ID, '')
                                                                  +'_'+ISNULL(a.ROUTE_ID, '')
                                                                  +'_'+ISNULL(a.OPERATION_ID, '')
                                                                  +'_'+ISNULL(a.RESOURCE_ID, ''))) AS resource_map_id
                                                  FROM dbo.TH_MST_SUB_OP_RESOURCE  AS a
                                                      INNER JOIN dbo.TH_MST_RESOURCE  AS b
                                                            ON  a.SUB_RESOURCE_ID = b.RESOURCE_ID 
                                                            AND a.MASTER_ID = @v_master_id 
                                                            AND a.MASTER_ID = b.MASTER_ID 
                                                            AND a.PLAN_ID = @v_plan_id 
                                                            AND a.PLAN_ID = b.PLAN_ID 
                                                            AND isnull(a.IS_VALID, 'Y') = 'Y' 
                                                            AND isnull(b.IS_VALID, 'Y') = 'Y' 
                                                            AND b.RESOURCE_TYPE = 'SUB'
                                                  GROUP BY 
                                                          a.SITE_ID
                                                        , a.ROUTE_ID
                                                        , a.OPERATION_ID
                                                        , a.ITEM_ID
                                                        , a.RESOURCE_ID
                                                        , isnull(RTRIM(LTRIM(a.ALT_ID)), 'SUB')
                                                        , RTRIM(LTRIM( ISNULL(a.ITEM_ID, '')
                                                                  +'_'+ISNULL(a.SITE_ID, '')
                                                                  +'_'+ISNULL(a.ROUTE_ID, '')
                                                                  +'_'+ISNULL(a.OPERATION_ID, '')
                                                                  +'_'+ISNULL(a.RESOURCE_ID, '')))
                                                )  AS a
                                        )  AS a
                                  WHERE a.resource_map_level = 2
                                )  AS d 
                      ON  a.SITE_ID = d.SITE_ID 
                      AND a.ITEM_ID = d.ITEM_ID 
                      AND a.ROUTE_ID = d.ROUTE_ID 
                      AND a.OPERATION_ID = d.OPERATION_ID 
                      AND a.RESOURCE_ID = d.RESOURCE_ID
                INNER JOIN dbo.TH_MST_ITEM_ROUTE_SITE  AS b
                      ON  a.MASTER_ID = b.MASTER_ID 
                      AND a.PLAN_ID = b.PLAN_ID 
                      AND a.ITEM_ID = b.ITEM_ID 
                      AND a.SITE_ID = b.SITE_ID 
                      AND a.ROUTE_ID = b.ROUTE_ID 
                      AND a.OPERATION_ID = b.OPERATION_ID 
                      AND isnull(b.IS_VALID, 'Y') = 'Y'                        
                INNER JOIN dbo.TH_MST_RESOURCE  AS c
                      ON  a.RESOURCE_ID = c.RESOURCE_ID 
                      AND A.MASTER_ID = c.MASTER_ID 
                      AND A.PLAN_ID = c.PLAN_ID 
                      AND isnull(c.IS_VALID, 'Y') = 'Y'
                      AND c.RESOURCE_TYPE = 'MAIN'
                /* 20170308 수정 CGJ
                INNER JOIN (
                                  SELECT 
                                          fci.ITEM_ID
                                        , fci.SITE_ID
                                        , fci.ROUTE_ID
                                        , fci.OPERATION_ID
                                        , fci.RESOURCE_ID
                                  FROM 
                                        (
                                          SELECT  a.ITEM_ID, a.SITE_ID, a.ROUTE_ID, a.OPERATION_ID, a.RESOURCE_ID, 
                                                  a.ALT_PRIORITY, a.TACT_TIME, a.TACT_TIME_UOM, a.YIELD, a.IS_USE
                                          FROM    dbo.TH_MST_OP_RESOURCE_CAL  AS a
                                          WHERE   a.MASTER_ID = @v_master_id 
                                          AND     a.PLAN_ID = @v_plan_id
                                          EXCEPT
                                          SELECT  a.ITEM_ID, a.SITE_ID, a.ROUTE_ID, a.OPERATION_ID, a.RESOURCE_ID, 
                                                  a.ALT_PRIORITY, a.TACT_TIME, a.TACT_TIME_UOM, a.YIELD, 'Y' AS is_use
                                          FROM    dbo.TH_MST_OP_RESOURCE  AS a
                                          WHERE   a.MASTER_ID = @v_master_id 
                                          AND     a.PLAN_ID = @v_plan_id
                                        )  AS fci
                                  GROUP BY 
                                          fci.ITEM_ID
                                        , fci.SITE_ID
                                        , fci.ROUTE_ID
                                        , fci.OPERATION_ID
                                        , fci.RESOURCE_ID
                                )  AS e
                      ON  a.ITEM_ID = e.ITEM_ID 
                      AND a.SITE_ID = e.SITE_ID 
                      AND a.ROUTE_ID = e.ROUTE_ID 
                      AND a.OPERATION_ID = e.OPERATION_ID 
                      AND a.RESOURCE_ID = e.RESOURCE_ID */ --20170308 수정 CGJ
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id
      UNION ALL
      SELECT  DISTINCT 
              a.MASTER_ID
            , a.PLAN_ID
            , a.SITE_ID
            , a.ROUTE_ID
            , a.OPERATION_ID
            , a.ITEM_ID
            , b.resource_map_id
            , b.RESOURCE_GROUP_ID
            , a.START_DATE AS start_dttm
            , a.END_DATE AS end_dttm
            , b.sub_resource_map_id
            , b.resource_map_level
            , a.ALT_PRIORITY
            , a.TACT_TIME
            , a.TACT_TIME_UOM
            , b.YIELD AS yield
            , NULL AS good_rate
            , NULL AS batch_rate
            , a.IS_USE AS is_use
            , NULL AS descr
            , NULL AS consume_res_rate
            , NULL AS prepare_time
            , 'HOUR' AS prepare_time_uom
      FROM  dbo.TH_MST_SUB_OP_RESOURCE_CAL  AS a
            INNER JOIN (
                              SELECT 
                                      a.SITE_ID
                                    , a.ROUTE_ID
                                    , a.OPERATION_ID
                                    , a.ITEM_ID
                                    , RTRIM(LTRIM(ISNULL(CAST(a.resource_map_id AS nvarchar(max)), '') + '::' + ISNULL(CAST(a.resource_map_level AS nvarchar(max)), ''))) AS resource_map_id
                                    , a.RESOURCE_ID
                                    , a.SUB_RESOURCE_ID
                                    , a.ALT_ID
                                    , a.RESOURCE_GROUP_ID
                                    , CASE CAST(a.resource_map_level AS float(53)) - 1
                                          WHEN a.alt_cnt THEN NULL
                                          ELSE RTRIM(LTRIM(ISNULL(CAST(a.resource_map_id AS nvarchar(max)), '') + '::' + ISNULL(CAST((CAST(a.resource_map_level AS float(53)) + 1) AS nvarchar(max)), '')))
                                      END AS sub_resource_map_id
                                    , a.resource_map_level AS resource_map_level
                                    , a.ALT_PRIORITY
                                    , a.TACT_TIME
                                    , a.TACT_TIME_UOM
                                    , a.YIELD
                                    , NULL AS is_first_setup
                                    , NULL AS good_rate
                                    , NULL AS batch_rate
                                    , a.consume_res_rate AS consume_res_rate
                                    , NULL AS descr
                              FROM 
                                    (
                                      SELECT 
                                              a.SITE_ID
                                            , a.ROUTE_ID
                                            , a.OPERATION_ID
                                            , a.ITEM_ID
                                            , a.resource_map_id AS resource_map_id
                                            , a.RESOURCE_ID
                                            , a.SUB_RESOURCE_ID
                                            , a.alt_id
                                            , CAST(rank() OVER(PARTITION BY a.resource_map_id
                                                               ORDER BY a.alt_id) AS float(53)) + 1 AS resource_map_level
                                            , count_big(a.alt_id) OVER(PARTITION BY a.resource_map_id) AS alt_cnt
                                            , a.RESOURCE_GROUP_ID
                                            , a.ALT_PRIORITY
                                            , a.TACT_TIME
                                            , a.TACT_TIME_UOM
                                            , a.consume_res_rate AS consume_res_rate
                                            , a.YIELD
                                      FROM 
                                            (
                                              SELECT 
                                                      a.SITE_ID
                                                    , a.ROUTE_ID
                                                    , a.OPERATION_ID
                                                    , a.ITEM_ID
                                                    , a.RESOURCE_ID
                                                    , a.SUB_RESOURCE_ID
                                                    , isnull(RTRIM(LTRIM(a.ALT_ID)), 'SUB') AS alt_id
                                                    , RTRIM(LTRIM(ISNULL(a.ITEM_ID, '')
                                                            +'_'+ ISNULL(a.SITE_ID, '')
                                                            +'_'+ ISNULL(a.ROUTE_ID, '')
                                                            +'_'+ ISNULL(a.OPERATION_ID, '')
                                                            +'_'+ ISNULL(a.RESOURCE_ID, ''))) AS resource_map_id
                                                    , c.RESOURCE_GROUP_ID
                                                    , a.ALT_PRIORITY
                                                    , a.TACT_TIME
                                                    , a.TACT_TIME_UOM
                                                    , isnull(a.CONSUME_RES_RATE, 1) AS consume_res_rate
                                                    , b.YIELD
                                              FROM dbo.TH_MST_SUB_OP_RESOURCE  AS a
                                                  INNER JOIN dbo.TH_MST_OP_RESOURCE  AS b
                                                        ON  a.MASTER_ID = b.MASTER_ID 
                                                        AND a.PLAN_ID = b.PLAN_ID 
                                                        AND a.SITE_ID = b.SITE_ID 
                                                        AND a.OPERATION_ID = b.OPERATION_ID 
                                                        AND a.ITEM_ID = b.ITEM_ID 
                                                        AND a.RESOURCE_ID = b.RESOURCE_ID 
                                                        AND isnull(b.IS_VALID, 'Y') = 'Y'
                                                  INNER JOIN dbo.TH_MST_RESOURCE  AS c
                                                        ON  a.MASTER_ID = c.MASTER_ID 
                                                        AND a.PLAN_ID = c.PLAN_ID 
                                                        AND a.SUB_RESOURCE_ID = c.RESOURCE_ID 
                                                        AND c.RESOURCE_TYPE = 'SUB'
                                                        AND isnull(c.IS_VALID, 'Y') = 'Y' 
                                              WHERE   a.MASTER_ID = @v_master_id 
                                              AND     a.PLAN_ID = @v_plan_id 
                                              AND     isnull(a.IS_VALID, 'Y') = 'Y'
                                            )  AS a
                                    )  AS a
                            )  AS b
                  ON  a.SITE_ID = b.SITE_ID 
                  AND a.ITEM_ID = b.ITEM_ID 
                  AND a.ROUTE_ID = b.ROUTE_ID 
                  AND a.OPERATION_ID = b.OPERATION_ID 
                  AND a.RESOURCE_ID = b.RESOURCE_ID 
                  AND a.SUB_RESOURCE_ID = b.SUB_RESOURCE_ID
            INNER JOIN (
                              SELECT 
                                      fci.ITEM_ID
                                    , fci.SITE_ID
                                    , fci.ROUTE_ID
                                    , fci.OPERATION_ID
                                    , fci.RESOURCE_ID
                                    , fci.SUB_RESOURCE_ID
                              FROM 
                                    (
                                      SELECT  a.ITEM_ID, a.SITE_ID, a.ROUTE_ID, a.OPERATION_ID, a.RESOURCE_ID, a.SUB_RESOURCE_ID, 
                                              a.ALT_ID, a.ALT_PRIORITY, a.TACT_TIME, a.TACT_TIME_UOM, a.IS_USE
                                      FROM    dbo.TH_MST_SUB_OP_RESOURCE_CAL  AS a
                                      WHERE   a.MASTER_ID = @v_master_id 
                                      AND     a.PLAN_ID = @v_plan_id
                                      EXCEPT
                                      SELECT  a.ITEM_ID, a.SITE_ID, a.ROUTE_ID, a.OPERATION_ID, a.RESOURCE_ID, a.SUB_RESOURCE_ID, 
                                              a.ALT_ID, a.ALT_PRIORITY, a.TACT_TIME, a.TACT_TIME_UOM, 'Y' AS is_use
                                      FROM    dbo.TH_MST_SUB_OP_RESOURCE  AS a
                                      WHERE   a.MASTER_ID = @v_master_id 
                                      AND     a.PLAN_ID = @v_plan_id
                                    )  AS fci
                              GROUP BY 
                                      fci.ITEM_ID
                                    , fci.SITE_ID
                                    , fci.ROUTE_ID
                                    , fci.OPERATION_ID
                                    , fci.RESOURCE_ID
                                    , fci.SUB_RESOURCE_ID
                            )  AS c
                  ON  a.ITEM_ID = c.ITEM_ID 
                  AND a.SITE_ID = c.SITE_ID 
                  AND a.ROUTE_ID = c.ROUTE_ID 
                  AND a.OPERATION_ID = c.OPERATION_ID 
                  AND a.RESOURCE_ID = c.RESOURCE_ID 
                  AND a.SUB_RESOURCE_ID = c.SUB_RESOURCE_ID

      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_OP_RES_GROUP_MAP_CAL', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_ROUTE
           (
            MASTER_ID, 
            PLAN_ID, 
            ROUTE_ID, 
            ROUTE_LEVEL, 
            MIN_TAT, 
            AVG_TAT, 
            MAX_TAT, 
            TAT_UOM, 
            IS_EARLY_PRODUCING_BUCKET, 
            IS_PREV_EPST, 
            IS_FORWARD_BUCKET, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.ROUTE_ID, 
            a.ROUTE_LEVEL, 
            NULL AS min_tat, 
            NULL AS avg_tat, 
            NULL AS max_tat, 
            NULL AS tat_uom, 
            a.IS_EARLY_PRODUCING_BUCKET, 
            a.IS_PREV_EPST, 
            a.IS_FORWARD_BUCKET, 
            a.DESCR
      FROM  dbo.TH_MST_ROUTE  AS a
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_ROUTE', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_RESOURCE
           (
            MASTER_ID, 
            PLAN_ID, 
            RESOURCE_ID, 
            RESOURCE_TYPE, 
            SITE_ID, 
            ROUTE_ID, 
            LOCATION_ID, 
            MULTI_PORT_COUNT, 
            UTILIZATION, 
            BATCH_TYPE, 
            IS_EXCEPTION, 
            IS_FINITE, 
            IS_DUMMY, 
            OFFTIME_SET_ID, 
            ATTRIBUTE_SET_ID, 
            ATTRIBUTE_CHECKER_ID, 
            INLINE_GROUP_ID, 
            RESOURCE_GROUP_ID, 
            RESOURCE_SETUP_GROUP_ID, 
            BATCH_RES_GROUP_ID, 
            MAX_SETUP_COUNT, 
            RAMPUP_RATE, 
            RAMPUP_TERM, 
            RAMPUP_UOM, 
            FIXED_TERM, 
            FIXED_TERM_UOM, 
            NCP_TERM, 
            NCP_TERM_UOM, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.RESOURCE_ID, 
            a.resource_type, 
            a.SITE_ID, 
            a.route_id, 
            a.LOCATION_ID, 
            a.multi_port_count, 
            a.UTILIZATION, 
            a.BATCH_TYPE, 
            a.IS_EXCEPTION, 
            a.IS_FINITE, 
            a.IS_DUMMY, 
            --a.RESOURCE_GROUP_ID, 
            a.OFFTIME_SET_ID,
            NULL AS attribute_set_id, 
            NULL AS attribute_checker_id, 
            a.INLINE_GROUP_ID, 
            a.RESOURCE_GROUP_ID AS resource_group_id$2, 
            a.resource_setup_group_id, 
            a.BATCH_RES_GROUP_ID, 
            a.CONCURRENT_SETUP_COUNT, 
            a.RAMPUP_RATE, 
            a.RAMPUP_TERM, 
            a.RAMPUP_UOM, 
            case when CAST(a.fixed_term AS float(53)) >= isnull(b.fixed_term, 0)  then CAST(a.fixed_term AS float(53)) 
                                                                                  else isnull(b.fixed_term, 0) 
            end  AS fixed_term, 
            a.fixed_term_uom, 
            case when CAST(a.ncp_term AS float(53)) >= isnull(b.ncp_term, 0)  then CAST(a.ncp_term AS float(53)) 
                                                                              else isnull(b.ncp_term, 0) 
            end  AS ncp_term, 
            a.ncp_term_uom, 
            NULL AS descr
      FROM 
           (
            SELECT 
                  a.MASTER_ID, 
                  a.PLAN_ID, 
                  a.RESOURCE_ID, 
                  b.resource_type AS resource_type, 
                  a.SITE_ID, 
                  a.LOCATION_ID, 
                  a.UTILIZATION, 
                  CASE b.resource_type
                      WHEN 'MAIN' THEN 
                                        case when isnull(a.MULTI_PORT_COUNT, 0) >= 1  then isnull(a.MULTI_PORT_COUNT, 0) 
                                                                                      else 1 
                                        end
                      ELSE isnull(a.MULTI_PORT_COUNT, 0)
                  END AS multi_port_count, 
                  a.BATCH_TYPE, 
                  a.IS_EXCEPTION, 
                  a.IS_FINITE, 
                  a.IS_DUMMY, 
                  a.INLINE_GROUP_ID, 
                  a.RESOURCE_GROUP_ID,
                  a.OFFTIME_SET_ID,
                  RTRIM(LTRIM(a.RESOURCE_SETUP_GROUP_ID)) AS resource_setup_group_id, 
                  a.BATCH_RES_GROUP_ID, 
                  a.CONCURRENT_SETUP_COUNT, 
                  a.RAMPUP_RATE, 
                  a.RAMPUP_TERM, 
                  a.RAMPUP_UOM, 
                  (isnull(a.FIXED_TERM, 0) / CASE a.FIXED_TERM_UOM
                                                  WHEN 'SECOND' THEN 86400
                                                  WHEN 'MINUTE' THEN 1440
                                                  WHEN 'HOUR' THEN 24
                                                  ELSE 1
                                             END) AS fixed_term, 
                  'DAY' AS fixed_term_uom, 
                  (isnull(a.NCP_TERM, 0) / CASE a.NCP_TERM_UOM
                                                WHEN 'SECOND' THEN 86400
                                                WHEN 'MINUTE' THEN 1440
                                                WHEN 'HOUR' THEN 24
                                                ELSE 1
                                              END) AS ncp_term, 
                  'DAY' AS ncp_term_uom, 
                  b.route_id AS route_id
            FROM 
                  dbo.TH_MST_RESOURCE  AS a 
                  INNER JOIN (
                                    SELECT 
                                          a.RESOURCE_ID, max(a.ROUTE_ID) AS route_id, 'MAIN' AS resource_type
                                    FROM  dbo.TH_MST_OP_RESOURCE  AS a
                                    WHERE a.MASTER_ID = @v_master_id 
                                    AND a.PLAN_ID = @v_plan_id 
                                    AND isnull(a.IS_VALID, 'Y') = 'Y' 
                                    --AND isnull(a.TACT_TIME, 0) > 0
                                    GROUP BY a.RESOURCE_ID
                                    UNION ALL
                                    SELECT 
                                          a.SUB_RESOURCE_ID AS resource_id, max(a.ROUTE_ID) AS route_id, 'SUB' AS resource_type
                                    FROM  dbo.TH_MST_SUB_OP_RESOURCE  AS a
                                    WHERE a.MASTER_ID = @v_master_id 
                                    AND   a.PLAN_ID = @v_plan_id 
                                    AND   isnull(a.IS_VALID, 'Y') = 'Y'
                                    GROUP BY a.SUB_RESOURCE_ID
                                  )  AS b
                        ON  a.RESOURCE_ID = b.RESOURCE_ID 
                  LEFT OUTER JOIN (
                                    SELECT
                                          a.SUB_RESOURCE_ID, max(b.RESOURCE_SETUP_GROUP_ID) AS resource_setup_group_id
                                    FROM  dbo.TH_MST_SUB_OP_RESOURCE  AS a
                                          INNER JOIN dbo.TH_MST_RESOURCE  AS b
                                                ON  a.MASTER_ID = b.MASTER_ID 
                                                AND a.PLAN_ID = b.PLAN_ID 
                                                AND a.RESOURCE_ID = b.RESOURCE_ID 
                                    WHERE a.MASTER_ID = @v_master_id 
                                    AND   a.PLAN_ID = @v_plan_id
                                    GROUP BY a.SUB_RESOURCE_ID
                                  )  AS c 
                        ON  a.RESOURCE_ID = c.SUB_RESOURCE_ID
                  WHERE a.MASTER_ID = @v_master_id 
                  AND   a.PLAN_ID = @v_plan_id 
                  AND   isnull(a.IS_VALID, 'Y') = 'Y'
           )  AS a 
            LEFT OUTER JOIN (
                              SELECT 
                                    a.SITE_ID, 
                                    (isnull(a.FIXED_TERM, 0) / CASE a.FIXED_TERM_UOM
                                                                    WHEN 'SECOND' THEN 86400
                                                                    WHEN 'MINUTE' THEN 1440
                                                                    WHEN 'HOUR' THEN 24
                                                                    ELSE 1
                                                               END) AS fixed_term, 
                                    'DAY' AS fixed_term_uom, 
                                    (isnull(a.NCP_TERM, 0) / CASE a.NCP_TERM_UOM
                                                                  WHEN 'SECOND' THEN 86400
                                                                  WHEN 'MINUTE' THEN 1440
                                                                  WHEN 'HOUR' THEN 24
                                                                  ELSE 1
                                                             END) AS ncp_term, 
                                    'DAY' AS ncp_term_uom
                             FROM dbo.TH_MST_SITE  AS a
                             WHERE a.MASTER_ID = @v_master_id AND a.PLAN_ID = @v_plan_id
                          )  AS b 
                  ON a.SITE_ID = b.SITE_ID

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_RESOURCE', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_RESOURCE_CAL
           (
            MASTER_ID, 
            PLAN_ID, 
            RESOURCE_ID, 
            START_DTTM, 
            END_DTTM, 
            UTILIZATION, 
            MULTI_PORT_COUNT, 
            MAX_SETUP_COUNT, 
            IS_FINITE, 
            IS_USE, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.RESOURCE_ID, 
            a.START_DATE, 
            a.END_DATE, 
            a.UTILIZATION, 
            a.MULTI_PORT_COUNT, 
            a.CONCURRENT_SETUP_COUNT, 
            a.IS_FINITE, 
            a.IS_USE, 
            NULL AS descr
      FROM  dbo.TH_MST_RESOURCE_CAL  AS a
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_RESOURCE_CAL', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_PLAN_BOM
           (
            MASTER_ID, 
            PLAN_ID, 
            PARENT_ITEM_ID, 
            CHILD_ITEM_ID, 
            SITE_ID, 
            ROUTE_ID, 
            OPERATION_ID, 
            BINNING_ID, 
            PRODUCTION_FLAG, 
            BOM_VERSION_ID, 
            PARENT_ITEM_RATE, 
            CHILD_ITEM_RATE, 
            ALT_ID, 
            ALT_PRIORITY, 
            ALT_RATE, 
            IN_MOVE_TIME, 
            OUT_MOVE_TIME, 
            MOVE_TIME_UOM, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            isnull(b.BIN_ITEM_ID, a.PARENT_ITEM_ID) AS parent_item_id, 
            a.child_item_id, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            isnull(b.BIN_ID, '-') AS binning_id, 
            isnull(b.PRODUCTION_FLAG, 'Y') AS production_flag, 
            a.BOM_VERSION_ID, 
            isnull(b.BIN_RATE, a.parent_item_rate) AS parent_item_rate, 
            a.child_item_rate, 
            a.ALT_ID, 
            a.ALT_PRIORITY, 
            a.ALT_RATE, 
            a.IN_MOVE_TIME, 
            a.OUT_MOVE_TIME, 
            a.MOVE_TIME_UOM, 
            NULL AS descr
      FROM 
           (
            SELECT 
                  a.MASTER_ID, 
                  a.PLAN_ID, 
                  a.PARENT_ITEM_ID, 
                  isnull(b.CHILD_ITEM_ID, a.CHILD_ITEM_ID) AS child_item_id, 
                  a.SITE_ID, 
                  a.ROUTE_ID, 
                  a.OPERATION_ID, 
                  a.BOM_VERSION_ID, 
                  a.PRODUCTION_RATE AS parent_item_rate, 
                  a.CONSUME_RATE AS child_item_rate, 
                  isnull(b.ALT_ID, A.ALT_ID)  AS ALT_ID,
                  isnull(b.ALT_PRIORITY, A.ALT_PRIORITY) AS ALT_PRIORITY,
                  isnull(b.ALT_RATE, A.ALT_RATE) AS ALT_RATE,
                  a.IN_MOVE_TIME, 
                  a.OUT_MOVE_TIME, 
                  a.MOVE_TIME_UOM
            FROM  dbo.TH_MST_PLAN_BOM  AS a 
                  LEFT OUTER JOIN dbo.TH_MST_ALT_ITEM  AS b 
                        ON  a.PARENT_ITEM_ID = b.PARENT_ITEM_ID 
                        AND a.CHILD_ITEM_ID = b.CHILD_ITEM_ID 
                        AND a.MASTER_ID = b.MASTER_ID 
                        AND a.PLAN_ID = b.PLAN_ID
            WHERE a.MASTER_ID = @v_master_id 
            AND   a.PLAN_ID = @v_plan_id 
            AND   isnull(a.IS_VALID, 'Y') = 'Y'
           )  AS a 
            LEFT OUTER JOIN dbo.TH_MST_BIN  AS b 
                  ON  a.PARENT_ITEM_ID = b.PARENT_ITEM_ID 
                  AND a.MASTER_ID = b.MASTER_ID 
                  AND a.PLAN_ID = b.PLAN_ID
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_PLAN_BOM', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_PLAN_BOM_CAL
           (
            MASTER_ID, 
            PLAN_ID, 
            PARENT_ITEM_ID, 
            CHILD_ITEM_ID, 
            SITE_ID, 
            ROUTE_ID, 
            OPERATION_ID, 
            BINNING_ID, 
            PRODUCTION_FLAG, 
            START_DTTM, 
            END_DTTM, 
            BOM_VERSION_ID, 
            PARENT_ITEM_RATE, 
            CHILD_ITEM_RATE, 
            ALT_ID, 
            ALT_PRIORITY, 
            ALT_RATE, 
            IN_MOVE_TIME, 
            OUT_MOVE_TIME, 
            MOVE_TIME_UOM, 
            IS_USE, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            isnull(b.BIN_ITEM_ID, a.PARENT_ITEM_ID) AS parent_item_id, 
            a.child_item_id, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            isnull(b.BIN_ID, '-') AS binning_id, 
            isnull(b.PRODUCTION_FLAG, 'Y') AS production_flag, 
            a.start_dttm, 
            a.end_dttm, 
            a.BOM_VERSION_ID, 
            isnull(b.BIN_RATE, a.parent_item_rate) AS parent_item_rate, 
            a.child_item_rate, 
            a.ALT_ID, 
            a.ALT_PRIORITY, 
            a.ALT_RATE, 
            a.IN_MOVE_TIME, 
            a.OUT_MOVE_TIME, 
            a.MOVE_TIME_UOM, 
            a.IS_USE, 
            NULL AS descr
      FROM 
          (
            SELECT 
                  a.MASTER_ID, 
                  a.PLAN_ID, 
                  a.PARENT_ITEM_ID, 
                  isnull(b.CHILD_ITEM_ID, a.CHILD_ITEM_ID) AS child_item_id, 
                  a.SITE_ID, 
                  a.ROUTE_ID, 
                  a.OPERATION_ID, 
                  a.START_DATE AS start_dttm, 
                  a.END_DATE AS end_dttm, 
                  a.BOM_VERSION_ID, 
                  a.PRODUCTION_RATE AS parent_item_rate, 
                  a.CONSUME_RATE AS child_item_rate, 
                  b.ALT_ID, 
                  b.ALT_PRIORITY, 
                  b.ALT_RATE, 
                  a.IN_MOVE_TIME, 
                  a.OUT_MOVE_TIME, 
                  a.MOVE_TIME_UOM, 
                  a.IS_USE
            FROM  dbo.TH_MST_PLAN_BOM_CAL  AS a 
                  LEFT OUTER JOIN dbo.TH_MST_ALT_ITEM  AS b 
                        ON   a.MASTER_ID = b.MASTER_ID 
                        AND a.PLAN_ID = b.PLAN_ID 
                        AND a.PARENT_ITEM_ID = b.PARENT_ITEM_ID 
                        AND a.CHILD_ITEM_ID = b.CHILD_ITEM_ID
            WHERE a.MASTER_ID = @v_master_id 
            AND   a.PLAN_ID = @v_plan_id
          ) AS a 
          LEFT OUTER JOIN dbo.TH_MST_BIN  AS b 
                ON   a.PARENT_ITEM_ID = b.PARENT_ITEM_ID 
                AND  a.MASTER_ID = b.MASTER_ID 
                AND  a.PLAN_ID = b.PLAN_ID
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_PLAN_BOM_CAL', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_OFFTIME
           (
            MASTER_ID, 
            PLAN_ID, 
            OFFTIME_SET_ID, 
            OFFTIME_ID, 
            START_DTTM, 
            END_DTTM, 
            REPEAT_TYPE, 
            OFFTIME_TERM, 
            OFFTIME_TERM_UOM, 
            IS_WO_OVERLAP, 
            IS_DO_OVERLAP, 
            IS_SETUP_OVERLAP, 
            DESCR
           )
      SELECT DISTINCT
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.RESOURCE_GROUP_ID AS offtime_set_id, 
            RTRIM(LTRIM(ISNULL(a.OFFTIME_TYPE_ID, '') 
                + '_' + ISNULL(replace(replace(replace(convert(nvarchar, a.START_DATE, 120), ':', ''), ' ', ''), '-', ''), '') 
                + '_' + isnull(b.REPEAT_TYPE, 'O'))) 
              AS offtime_id, 
            case when a.START_DATE >= d.PLAN_START_DTTM then a.START_DATE else d.PLAN_START_DTTM end AS start_dttm, 
            max(a.END_DATE) AS end_dttm, 
            isnull(b.REPEAT_TYPE, 'O') AS repeat_type, 
            max(a.OFFTIME_TERM) AS offtime_term, 
            a.OFFTIME_TERM_UOM, 
            CASE WHEN max(a.OFFTIME_TERM) > 1440 THEN 'N' ELSE b.IS_WO_OVERLAP END AS IS_WO_OVERLAP, 
            b.IS_DO_OVERLAP, 
            b.IS_SETUP_OVERLAP, 
            max(b.DESCR) AS descr
      FROM  dbo.TH_MST_OFF_CALENDAR  AS a 
            INNER JOIN dbo.TH_MST_OFFTYPE_INFO  AS b
                  ON  a.MASTER_ID = b.MASTER_ID 
                  AND a.PLAN_ID = b.PLAN_ID 
                  AND a.OFFTIME_TYPE_ID = b.OFFTIME_TYPE_ID 
            INNER JOIN dbo.TH_MST_RESOURCE  AS c
                  ON  a.MASTER_ID = c.MASTER_ID 
                  AND a.PLAN_ID = c.PLAN_ID 
                  AND a.RESOURCE_GROUP_ID = c.OFFTIME_SET_ID 
                  AND c.IS_VALID = 'Y'
            INNER      JOIN dbo.TH_MST_PLAN  AS d
                  ON  a.MASTER_ID = d.MASTER_ID 
                  AND a.PLAN_ID = d.PLAN_ID 
                  AND a.END_DATE > d.PLAN_START_DTTM
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id 
      AND   a.START_DATE < a.END_DATE 
      AND   isnull(a.OFFTIME_TERM, 0) > 0 
      GROUP BY 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.RESOURCE_GROUP_ID, 
            RTRIM(LTRIM(ISNULL(a.OFFTIME_TYPE_ID, '') 
                + '_' + ISNULL(replace(replace(replace(convert(nvarchar, a.START_DATE, 120), ':', ''), ' ', ''), '-', ''), '') 
                + '_' + isnull(b.REPEAT_TYPE, 'O'))), 
            case when a.START_DATE >= d.PLAN_START_DTTM then a.START_DATE else d.PLAN_START_DTTM end,
            isnull(b.REPEAT_TYPE, 'O'), 
            a.OFFTIME_TERM_UOM, 
            b.IS_WO_OVERLAP, 
            b.IS_DO_OVERLAP, 
            b.IS_SETUP_OVERLAP

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_OFFTIME', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_SETUP_MATRIX
           (
            MASTER_ID, 
            PLAN_ID, 
            RESOURCE_SETUP_GROUP_ID, 
            FROM_SETUP_GROUP_ID, 
            TO_SETUP_GROUP_ID, 
            SETUP_TIME, 
            SETUP_TIME_UOM, 
            FIRST_SETUP_TIME, 
            FIRST_SETUP_TIME_UOM, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.RESOURCE_SETUP_GROUP_ID, 
            a.FROM_SETUP_ID, 
            a.TO_SETUP_ID, 
            a.SETUP_TIME, 
            a.SETUP_TIME_UOM, 
            a.first_setup_time, 
            a.SETUP_TIME_UOM AS setup_time_uom$2, 
            a.DESCR
      FROM 
          (
            SELECT 
                  SSMAROWNUM.MASTER_ID, 
                  SSMAROWNUM.PLAN_ID, 
                  SSMAROWNUM.RESOURCE_SETUP_GROUP_ID, 
                  SSMAROWNUM.FROM_SETUP_ID, 
                  SSMAROWNUM.TO_SETUP_ID, 
                  SSMAROWNUM.SETUP_TIME, 
                  case when SSMAROWNUM.SETUP_TIME >= SSMAROWNUM.FIRST_SETUP_TIME  then SSMAROWNUM.SETUP_TIME 
                                                                                  else SSMAROWNUM.FIRST_SETUP_TIME 
                  end  AS first_setup_time, 
                  SSMAROWNUM.SETUP_TIME_UOM, 
                  SSMAROWNUM.DESCR, 
                  rank() OVER(PARTITION BY SSMAROWNUM.RESOURCE_SETUP_GROUP_ID, SSMAROWNUM.FROM_SETUP_ID, SSMAROWNUM.TO_SETUP_ID
                              ORDER     BY SSMAROWNUM.setup_info_seq, 
                                            SSMAROWNUM.SETUP_TIME DESC, 
                                            SSMAROWNUM.SETUP_LEVEL DESC, 
                                            SSMAROWNUM.SETUP_CATEGORY_ID, 
                                            SSMAROWNUM.ROWNUM) AS r
            FROM 
                 (
                  SELECT 
                        MASTER_ID, 
                        PLAN_ID, 
                        RESOURCE_SETUP_GROUP_ID, 
                        FROM_SETUP_ID, 
                        TO_SETUP_ID, 
                        SETUP_TIME, 
                        FIRST_SETUP_TIME, 
                        SETUP_TIME_UOM, 
                        DESCR, 
                        setup_info_seq, 
                        SETUP_LEVEL, 
                        SETUP_CATEGORY_ID, 
                        ROW_NUMBER() OVER(ORDER BY SSMAPSEUDOCOLUMN) AS ROWNUM
                  FROM 
                       (
                        SELECT 
                              a.MASTER_ID, 
                              a.PLAN_ID, 
                              a.RESOURCE_SETUP_GROUP_ID, 
                              a.FROM_SETUP_ID, 
                              a.TO_SETUP_ID, 
                              a.SETUP_TIME, 
                              a.FIRST_SETUP_TIME, 
                              a.SETUP_TIME_UOM, 
                              a.DESCR, 
                              a.setup_info_seq, 
                              a.SETUP_LEVEL, 
                              a.SETUP_CATEGORY_ID, 
                              0 AS SSMAPSEUDOCOLUMN
                        FROM 
                             (
                              SELECT DISTINCT 
                                    a.MASTER_ID, 
                                    a.PLAN_ID, 
                                    a.RESOURCE_SETUP_GROUP_ID, 
                                    b.SETUP_LEVEL, 
                                    a.SETUP_CATEGORY_ID, 
                                    a.FROM_SETUP_ID, 
                                    a.TO_SETUP_ID, 
                                    a.SETUP_TIME, 
                                    a.FIRST_SETUP_TIME, 
                                    a.SETUP_TIME_UOM, 
                                    a.DESCR, 
                                    1 AS setup_info_seq
                              FROM  dbo.TH_MST_SETUP_TIME  AS a
                                    INNER JOIN dbo.TH_MST_SETUP_CATEGORY  AS b
                                          ON  a.MASTER_ID = b.MASTER_ID 
                                          AND a.PLAN_ID = b.PLAN_ID 
                                          AND a.SETUP_CATEGORY_ID = b.SETUP_CATEGORY_ID 
                              WHERE a.MASTER_ID = @v_master_id 
                              AND   a.PLAN_ID = @v_plan_id 
                              AND   isnull(a.SETUP_TIME, 0) > 0
                              UNION ALL
                              SELECT DISTINCT 
                                    a.MASTER_ID, 
                                    a.PLAN_ID, 
                                    a.RESOURCE_SETUP_GROUP_ID, 
                                    b.SETUP_LEVEL, 
                                    a.SETUP_CATEGORY_ID, 
                                    a.TO_SETUP_ID AS from_setup_id, 
                                    a.FROM_SETUP_ID AS to_setup_id, 
                                    a.SETUP_TIME, 
                                    a.FIRST_SETUP_TIME, 
                                    a.SETUP_TIME_UOM, 
                                    a.DESCR, 
                                    2 AS setup_info_seq
                              FROM  dbo.TH_MST_SETUP_TIME  AS a
                                    INNER JOIN dbo.TH_MST_SETUP_CATEGORY  AS b
                                          ON  a.MASTER_ID = b.MASTER_ID 
                                          AND a.PLAN_ID = b.PLAN_ID 
                                          AND a.SETUP_CATEGORY_ID = b.SETUP_CATEGORY_ID 
                              WHERE a.MASTER_ID = @v_master_id 
                              AND   a.PLAN_ID = @v_plan_id 
                              AND   isnull(a.SETUP_TIME, 0) > 0
                             )  AS a
                       )  AS SSMAPSEUDO
                 )  AS SSMAROWNUM
           )  AS a
      WHERE a.r = 1
      ORDER BY a.RESOURCE_SETUP_GROUP_ID, a.FROM_SETUP_ID, a.TO_SETUP_ID

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_SETUP_MATRIX', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_NET_DEMAND
           (
            MASTER_ID, 
            PLAN_ID, 
            DEMAND_ID, 
            SALES_MODEL_ID, 
            SHIPPING_DATE, 
            DUE_DATE, 
            DUE_FENCE_DATE, 
            EARLY_PRODUCING_TERM, 
            EARLY_PRODUCING_TERM_UOM, 
            QTY, 
            SPLIT_QTY, 
            ORDER_TYPE, 
            DEMAND_TYPE, 
            PRODUCING_TYPE, 
            PRIORITY, 
            PRIORITY_GROUP_CODE, 
            ATTRIBUTE_CHECKER_ID, 
            DEMAND_GROUP_ID, 
            LATE_TYPE,
            DESCR, 
            MOVE_TIME_RATE, 
            BUFFER_TIME_RATE, 
            IS_EXCEPTION,
            IS_CONSUME
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.NET_DEMAND_ID, 
            a.SALES_MODEL AS sales_model_id, 
            DATEADD(MINUTE, 1440 + @v_daydiff, a.SHIPPING_DATE)   AS SHIPPING_DATE, 
            DATEADD(MINUTE, 1440 + @v_daydiff, a.DUE_DATE)        AS DUE_DATE, 
            DATEADD(MINUTE, 1440 + @v_daydiff, a.DUE_FENCE_DATE)  AS DUE_FENCE_DATE, 
            a.EARLY_PRODUCING_TERM, 
            a.EARLY_PRODUCING_TERM_UOM, 
            a.QTY, 
            a.SPLIT_QTY, 
            a.ORDER_TYPE, 
            CASE WHEN isnull(b.fix_demand_id, '-') = a.NET_DEMAND_ID  THEN 'FIX'
                 ELSE CASE c.PLAN_TYPE
                          WHEN 'PRE' THEN a.DEMAND_TYPE
                          ELSE 'SYNC'
                      END
            END  AS demand_type, 
            a.PRODUCING_TYPE, 
            a.DEMAND_PRIORITY AS priority, 
            a.DEMAND_GROUP_PRIORITY AS priority_group_code, 
            a.ATTRIBUTE_CHECKER_ID, 
            a.NET_DEMAND_ID AS demand_group_id,       -- 2016.11.15 
            --'FENCEDATE_OVERLAP' AS LATE_TYPE,
            NULL AS LATE_TYPE,
            a.DESCR, 
            1 AS move_time_rate, 
            1 AS buffer_time_rate, 
            a.IS_EXCEPTION,
            A.IS_CONSUME            
      FROM  dbo.TH_DPP_NET_DEMAND  AS a 
            LEFT OUTER JOIN (
                              SELECT DISTINCT a.DEMAND_ID AS fix_demand_id
                              FROM  dbo.TH_MST_FIXED_PLAN  AS a
                                    INNER JOIN dbo.TH_MST_ITEM  AS b
                                          ON  a.MASTER_ID = b.MASTER_ID 
                                          AND a.PLAN_ID = b.PLAN_ID
                                          AND a.ITEM_ID = b.ITEM_ID 
                                          AND b.ITEM_TYPE = 'P' 
                              WHERE a.MASTER_ID = @v_master_id 
                              AND   a.PLAN_ID = @v_plan_id 
                              AND   a.PO_TYPE = 'FIX' 
                              AND   RTRIM(LTRIM(a.DEMAND_ID)) IS NOT NULL 
                            ) AS b 
                  ON  a.NET_DEMAND_ID = b.fix_demand_id
            INNER JOIN dbo.TH_MST_PLAN C
                  ON  a.MASTER_ID = c.MASTER_ID 
                  AND a.PLAN_ID = c.PLAN_ID
            WHERE a.MASTER_ID = @v_master_id 
            AND   a.PLAN_ID = @v_plan_id 
            AND   a.IS_SCHEDULE = 'Y'

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_NET_DEMAND', 'INSERT', @@ROWCOUNT, null, null, null 

      BEGIN
      
        UPDATE TH_ENG_NET_DEMAND
        SET    TH_ENG_NET_DEMAND.DUE_DATE =       CASE WHEN DUE_DATE > PLAN_START_DTTM + DEMAND_HORIZON  THEN PLAN_START_DTTM + DEMAND_HORIZON
                                                       WHEN DUE_DATE < PLAN_START_DTTM                   THEN PLAN_START_DTTM + 1
                                                       ELSE DUE_DATE
                                                  END,
               TH_ENG_NET_DEMAND.DUE_FENCE_DATE = CASE WHEN DUE_FENCE_DATE > PLAN_START_DTTM + DEMAND_HORIZON THEN PLAN_START_DTTM + DEMAND_HORIZON
                                                       WHEN DUE_FENCE_DATE < PLAN_START_DTTM                  THEN PLAN_START_DTTM + 1
                                                  ELSE DUE_FENCE_DATE
                                                  END,
               TH_ENG_NET_DEMAND.SHIPPING_DATE  = CASE WHEN SHIPPING_DATE > PLAN_START_DTTM + DEMAND_HORIZON THEN PLAN_START_DTTM + DEMAND_HORIZON
                                                       WHEN SHIPPING_DATE < PLAN_START_DTTM                  THEN PLAN_START_DTTM + 1
                                                  ELSE SHIPPING_DATE
                                                  END
        FROM   TH_ENG_NET_DEMAND A,
               TH_ENG_PLAN_INFO B
        WHERE  A.MASTER_ID = B.MASTER_ID
        AND    A.PLAN_ID = B.PLAN_ID
        AND    A.MASTER_ID = @v_master_id
        AND    A.PLAN_ID = @v_plan_id

        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_NET_DEMAND-DUE_DATE', 'UPDATE', @@ROWCOUNT, null, null, null 

      END

