      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_DEMAND_ATTRIBUTE', 'INSERT', @@ROWCOUNT, null, null, null 
      
     
      --LOG 생성
      --EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_DEMAND_ATTRIBUTE', 'DELETE', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_FIXED_PLAN
           (
            MASTER_ID, 
            PLAN_ID, 
            WORK_ORDER_ID, 
            WORK_ORDER_SEQ, 
            SITE_ID, 
            ROUTE_ID, 
            OPERATION_ID, 
            ITEM_ID, 
            RESOURCE_ID, 
            SUB_RESOURCE_ID, 
            START_DTTM, 
            END_DTTM, 
            OPERATION_QTY, 
            COMPLETE_QTY, 
            LOT_ID, 
            IS_FIXED, 
            IS_PREV_SCHEDULE, 
            KEEP_WORK_TIME_TYPE, 
            KEEP_QTY_TYPE, 
            SALES_MODEL_ID, 
            ATTRIBUTE_SET_ID, 
            DEMAND_ID, 
            IS_NOH_CONSUME, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.WORK_ORDER_ID, 
            a.WORK_ORDER_SEQ, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            a.ITEM_ID, 
            a.RESOURCE_ID, 
            NULL AS sub_resource_id, 
            a.START_DATE, 
            a.END_DATE, 
            a.OPERATION_QTY, 
            a.COMPLETE_QTY, 
            a.LOT_ID, 
            a.IS_FIXED, 
            a.IS_PREV_SCHEDULE, 
            a.KEEP_WORK_TIME_TYPE, 
            a.KEEP_QTY_TYPE, 
            NULL AS sales_model_id, 
            NULL AS attribute_set_id, 
            a.demand_id, 
            a.IS_NOH_CONSUME, 
            NULL AS descr
      FROM 
           (
            SELECT 
                  a.MASTER_ID, 
                  a.PLAN_ID, 
                  a.WORK_ORDER_ID, 
                  a.WORK_ORDER_SEQ, 
                  a.SITE_ID, 
                  a.ROUTE_ID, 
                  a.OPERATION_ID, 
                  a.ITEM_ID, 
                  a.RESOURCE_ID, 
                  a.SUB_RESOURCE_ID, 
                  a.START_DATE, 
                  a.END_DATE, 
                  a.OPERATION_QTY, 
                  a.COMPLETE_QTY, 
                  a.LOT_ID, 
                  a.IS_FIXED, 
                  a.IS_PREV_SCHEDULE, 
                  a.KEEP_WORK_TIME_TYPE, 
                  a.KEEP_QTY_TYPE, 
                  a.TOP_WORK_ORDER_ID, 
                  a.IS_NOH_CONSUME, 
                  CASE WHEN c.ITEM_ID IS NULL THEN NULL
                       ELSE RTRIM(LTRIM(a.DEMAND_ID))
                  END  AS demand_id
            FROM  dbo.TH_MST_FIXED_PLAN  AS a 
                  LEFT OUTER JOIN (
                                    SELECT  a.ITEM_ID
                                    FROM    dbo.TH_DPP_NET_DEMAND  AS a
                                    WHERE   a.MASTER_ID = @v_master_id 
                                    AND     a.PLAN_ID = @v_plan_id
                                    GROUP BY a.ITEM_ID
                                  )  AS c 
                        ON a.ITEM_ID = c.ITEM_ID
                  INNER JOIN dbo.TH_MST_PLAN  AS b
                        ON  a.MASTER_ID = b.MASTER_ID 
                        AND a.PLAN_ID = b.PLAN_ID 
                        AND a.START_DATE >= b.PLAN_START_DTTM 
            WHERE a.MASTER_ID = @v_master_id 
            AND   a.PLAN_ID = @v_plan_id 
            AND   a.PO_TYPE = 'FIX' 
            AND   isnull(a.COMPLETE_QTY, 0) > 0
            UNION ALL
            SELECT 
                  a.MASTER_ID, 
                  a.PLAN_ID, 
                  a.WORK_ORDER_ID, 
                  a.WORK_ORDER_SEQ, 
                  a.SITE_ID, 
                  a.ROUTE_ID, 
                  a.OPERATION_ID, 
                  a.ITEM_ID, 
                  a.RESOURCE_ID, 
                  a.SUB_RESOURCE_ID, 
                  a.START_DATE, 
                  a.END_DATE, 
                  a.OPERATION_QTY, 
                  a.COMPLETE_QTY, 
                  a.LOT_ID, 
                  a.IS_FIXED, 
                  a.IS_PREV_SCHEDULE, 
                  a.KEEP_WORK_TIME_TYPE, 
                  a.KEEP_QTY_TYPE, 
                  a.TOP_WORK_ORDER_ID, 
                  a.IS_NOH_CONSUME, 
                  RTRIM(LTRIM(a.DEMAND_ID)) AS demand_id
            FROM  dbo.TH_MST_FIXED_PLAN  AS a
                  INNER JOIN dbo.TH_MST_ITEM_ROUTE_SITE  AS b
                        ON  a.MASTER_ID = b.MASTER_ID 
                        AND a.PLAN_ID = b.PLAN_ID 
                        AND a.ITEM_ID = b.ITEM_ID 
                        AND a.SITE_ID = b.SITE_ID 
                        AND a.ROUTE_ID = b.ROUTE_ID 
                        AND a.OPERATION_ID = b.OPERATION_ID 
                  INNER JOIN dbo.TH_MST_PLAN  AS c
                        ON  a.MASTER_ID = c.MASTER_ID 
                        AND a.PLAN_ID = c.PLAN_ID 
                        AND a.START_DATE >= c.PLAN_START_DTTM 
            WHERE a.MASTER_ID = @v_master_id 
            AND   a.PLAN_ID = @v_plan_id 
            AND   a.PO_TYPE = 'SYNC' 
            AND   isnull(a.COMPLETE_QTY, 0) > 0 
            AND   isnull(RTRIM(LTRIM(a.KEEP_WORK_TIME_TYPE)), 'RE_PLAN') != 'RE_PLAN'
            UNION ALL
            SELECT 
                  a.MASTER_ID, 
                  a.PLAN_ID, 
                  a.WORK_ORDER_ID, 
                  a.WORK_ORDER_SEQ, 
                  a.SITE_ID, 
                  a.ROUTE_ID, 
                  a.OPERATION_ID, 
                  a.ITEM_ID, 
                  a.RESOURCE_ID, 
                  a.SUB_RESOURCE_ID, 
                  a.START_DATE, 
                  a.END_DATE, 
                  a.OPERATION_QTY, 
                  a.COMPLETE_QTY, 
                  a.LOT_ID, 
                  a.IS_FIXED, 
                  a.IS_PREV_SCHEDULE, 
                  a.KEEP_WORK_TIME_TYPE, 
                  a.KEEP_QTY_TYPE, 
                  a.TOP_WORK_ORDER_ID, 
                  a.IS_NOH_CONSUME, 
                  RTRIM(LTRIM(a.DEMAND_ID)) AS demand_id
            FROM  dbo.TH_MST_FIXED_PLAN  AS a
                  INNER JOIN dbo.TH_MST_ITEM_ROUTE_SITE  AS b
                        ON  a.MASTER_ID = b.MASTER_ID 
                        AND a.PLAN_ID = b.PLAN_ID 
                        AND a.ITEM_ID = b.ITEM_ID 
                        AND a.SITE_ID = b.SITE_ID 
                        AND a.ROUTE_ID = b.ROUTE_ID 
                        AND a.OPERATION_ID = b.OPERATION_ID 
                  INNER JOIN dbo.TH_MST_PLAN  AS c
                        ON  a.MASTER_ID = c.MASTER_ID 
                        AND a.PLAN_ID = c.PLAN_ID 
                        AND a.START_DATE >= c.PLAN_START_DTTM 
            WHERE a.MASTER_ID = @v_master_id 
            AND   a.PLAN_ID = @v_plan_id 
            AND   a.PO_TYPE IN ('EXP', 'REPLAN') 
            AND   isnull(a.COMPLETE_QTY, 0) > 0 
            --AND   RTRIM(LTRIM(a.DEMAND_ID)) IS NOT NULL
           )  AS a
      WHERE EXISTS (
                    SELECT 1
                    FROM   dbo.TH_MST_OP_RESOURCE X
                    WHERE  X.MASTER_ID = A.MASTER_ID
                    AND    X.PLAN_ID = A.PLAN_ID
                    AND    X.ITEM_ID = A.ITEM_ID 
                    AND    X.SITE_ID = A.SITE_ID 
                    AND    X.ROUTE_ID = A.ROUTE_ID 
                    AND    X.OPERATION_ID = A.OPERATION_ID 
                    AND    X.RESOURCE_ID = A.RESOURCE_ID
                   )
    
      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_FIXED_PLAN', 'INSERT', @@ROWCOUNT, null, null, null 
     
      INSERT INTO dbo.TH_ENG_STOCK_PLAN
           (
            MASTER_ID, 
            PLAN_ID, 
            STOCK_SEQ, 
            ITEM_ID, 
            SITE_ID, 
            ROUTE_ID, 
            OPERATION_ID, 
            RECEIVING_DTTM, 
            QTY, 
            LOT_ID, 
            WORK_ORDER_ID, 
            DEMAND_ID,
            STOCK_STATUS, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.STOCK_SEQ, 
            a.ITEM_ID, 
            a.SITE_ID, 
            a.ROUTE_ID, 
            a.OPERATION_ID, 
            a.RECEIVING_DTTM, 
            a.QTY, 
            RTRIM(LTRIM(a.LOT_ID)) AS lot_id, 
            RTRIM(LTRIM(a.WORK_ORDER_ID)) AS work_order_id, 
            RTRIM(LTRIM(a.STOCK_ATTB_5))  AS DEMAND_ID, 
            a.STOCK_STATUS, 
            a.DESCR
      FROM dbo.TH_MST_STOCK_PLAN  AS a
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id 
      AND   isnull(a.QTY, 0) > 0
      AND   ISNULL(a.STOCK_ATTB_3, '-') = '-'       -- INSTANCE 간 STOCK 정보

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_STOCK_PLAN', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_WIP
           (
            MASTER_ID, 
            PLAN_ID, 
            WIP_SEQ, 
            ITEM_ID, 
            ROUTE_ID, 
            SITE_ID, 
            OPERATION_ID, 
            RESOURCE_ID, 
            SUB_RESOURCE_ID, 
            START_DTTM, 
