            QTY, 
            WORK_ORDER_ID, 
            DEMAND_ID, 
            LOT_ID, 
            ATTRIBUTE_SET_ID, 
            WIP_STATUS, 
            RELEASE_DTTM, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.WIP_SEQ, 
            a.ITEM_ID, 
            a.ROUTE_ID, 
            a.SITE_ID, 
            a.OPERATION_ID, 
            a.RESOURCE_ID, 
            a.SUB_RESOURCE_ID, 
            a.START_DATE, 
            a.END_DATE, 
            a.COMPLETE_QTY AS qty, 
            a.WORK_ORDER_ID, 
            NULL AS demand_id, 
            a.LOT_ID, 
            NULL AS attribute_set_id, 
            a.WIP_STATUS, 
            a.RELEASE_DTTM, 
            a.DESCR
      FROM  dbo.TH_MST_WIP  AS a
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id 
      AND   isnull(a.COMPLETE_QTY, 0) > 0

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_WIP', 'INSERT', @@ROWCOUNT, null, null, null 

     UPDATE SY_FP_PLAN_STATUS_H
            SET 
               INBOUND_STEP = '3',
               UPDATE_ID = @v_proc_name, 
               UPDATE_TIME = sysdatetime()
         FROM SY_FP_PLAN_STATUS_H  AS a
         WHERE 
            a.INSTANCE_ID = @v_master_id AND 
            a.PLAN_ID = @v_plan_id
       
      INSERT INTO dbo.TH_ENG_BOD
           (
            MASTER_ID, 
            PLAN_ID, 
            BOD_ID, 
            FROM_SITE_ID, 
            TO_SITE_ID, 
            TRANSPORT_MODE, 
            TRANSPORT_TIME, 
            TRANSPORT_TIME_UOM, 
            BOD_START_DTTM, 
            BOD_PATTERN_ID, 
            FIXED_TERM, 
            FIXED_TERM_UOM, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.BOD_ID, 
            a.FROM_SITE_ID, 
            a.TO_SITE_ID, 
            a.TRANSPORT_MODE, 
            a.TRANSPORT_TIME, 
            a.TRANSPORT_TIME_UOM, 
            a.BOD_START_DTTM, 
            a.BOD_PATTERN_ID, 
            isnull(a.FIXED_TERM, 0) AS fixed_term, 
            a.FIXED_TERM_UOM, 
            a.DESCR
      FROM  dbo.TH_MST_BOD  AS a
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_BOD', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_BOD_CAL
           (
            MASTER_ID, 
            PLAN_ID, 
            BOD_ID, 
            START_DTTM, 
            END_DTTM, 
            TRANSPORT_TIME, 
            TRANSPORT_TIME_UOM, 
            BOD_START_DTTM, 
            BOD_PATTERN_ID, 
            IS_USE, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.BOD_ID, 
            a.START_DATE, 
            a.END_DATE, 
            a.TRANSPORT_TIME, 
            a.TRANSPORT_TIME_UOM, 
            a.BOD_START_TIME, 
            a.BOD_PATTERN_ID, 
            isnull(RTRIM(LTRIM(a.IS_USE)), 'Y') AS is_use, 
            NULL AS descr
      FROM  dbo.TH_MST_BOD_CAL  AS a
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id
      UNION ALL
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.BOD_ID, 
            DATEADD(SS, 1, b.PLAN_START_DTTM) AS start_dttm, 
            DATEADD(SS, (a.FIXED_TERM * CASE a.FIXED_TERM_UOM WHEN 'SECOND' THEN 1 
                                                              WHEN 'MINUTE' THEN 60 
                                                              WHEN 'HOUR' THEN 1440 
                                                              ELSE 86400 END), b.PLAN_START_DTTM) AS end_dttm, 
            a.TRANSPORT_TIME, 
            a.TRANSPORT_TIME_UOM, 
            a.BOD_START_DTTM, 
            a.BOD_PATTERN_ID, 
            'N' AS is_use, 
            'BOD_FIX' AS descr
      FROM  dbo.TH_ENG_BOD  AS a
            INNER JOIN dbo.TH_ENG_PLAN_INFO  AS b
                  ON  a.MASTER_ID = b.MASTER_ID 
                  AND a.PLAN_ID = b.PLAN_ID 
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id 
      AND   isnull(a.FIXED_TERM, 0) > 0

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_BOD_CAL', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_ITEM_BOD
           (
            MASTER_ID, 
            PLAN_ID, 
            ITEM_ID, 
            BOD_ID, 
            ALT_PRIORITY, 
            ALT_RATE, 
            TRANSFER_LOT_SIZE, 
            IS_PREV_LOT_SIZE, 
            IS_PULL, 
            PRE_BUFFER_TIME, 
            POST_BUFFER_TIME, 
            BUFFER_TIME_UOM, 
            ROUTE_SELECTOR_ID, 
            EARLY_PRODUCING_TERM, 
            EARLY_PRODUCING_TERM_UOM, 
            DESCR
           )
      SELECT 
            @v_master_id, 
            @v_plan_id, 
            a.ITEM_ID, 
            a.BOD_ID, 
            a.ALT_PRIORITY, 
            CASE isnull(d.is_priority, 'Y') WHEN 'N' THEN a.ALT_RATE ELSE 0 END AS alt_rate, 
            a.TRANSPORT_LOT_SIZE, 
            a.IS_PREV_LOT_SIZE, 
            a.IS_PULL, 
            a.PRE_BUFFER_TIME, 
            a.POST_BUFFER_TIME, 
            a.BUFFER_TIME_UOM, 
            NULL AS route_selector_id, 
            CASE WHEN b.item_id IS NULL THEN 
                    CASE WHEN c.SITE_ID IS NULL THEN 
                            case when CAST(a.early_producing_term AS float(53)) >= 0 then CAST(a.early_producing_term AS float(53))
                                 else 0
                            end
                         ELSE a.early_producing_term
                    END
                 ELSE a.early_producing_term
            END  AS early_producing_term, 
            a.early_producing_term_uom, 
            NULL AS descr
      FROM 
          (
            SELECT 
                  a.BOD_ID, 
                  a.ITEM_ID, 
                  b.FROM_SITE_ID, 
                  b.TO_SITE_ID, 
                  a.ALT_PRIORITY, 
                  a.ALT_RATE, 
                  a.IS_ALT_LOCKED, 
                  a.TRANSPORT_LOT_SIZE, 
                  a.IS_PREV_LOT_SIZE, 
                  a.IS_PULL, 
                  a.PRE_BUFFER_TIME, 
                  a.POST_BUFFER_TIME, 
                  a.BUFFER_TIME_UOM, 
                  a.IS_VALID, 
                  (isnull(a.EARLY_PRODUCING_TERM, 0) / CASE a.EARLY_PRODUCING_TERM_UOM
                                                            WHEN 'SECOND' THEN 86400
                                                            WHEN 'MINUTE' THEN 1440
                                                            WHEN 'HOUR'   THEN 24
                                                                          ELSE 1
                                                            END) AS early_producing_term, 
                  'DAY' AS early_producing_term_uom
            FROM  dbo.TH_MST_ITEM_BOD  AS a
                  INNER JOIN dbo.TH_MST_BOD  AS b
                        ON  a.MASTER_ID = b.MASTER_ID 
                        AND a.PLAN_ID = b.PLAN_ID 
                        AND a.BOD_ID = b.BOD_ID 
            WHERE a.MASTER_ID = @v_master_id 
            AND   a.PLAN_ID = @v_plan_id 
            AND   isnull(a.IS_VALID, 'Y') = 'Y'
          ) AS a 
          LEFT OUTER JOIN (
                            SELECT 
                                  a.CHILD_ITEM_ID AS item_id, a.SITE_ID
                            FROM  dbo.TH_MST_PLAN_BOM  AS a
                                  INNER JOIN dbo.TH_MST_ITEM_ROUTE_SITE  AS b
                                        ON  a.MASTER_ID = b.MASTER_ID 
                                        AND a.PLAN_ID = b.PLAN_ID 
                                        AND a.SITE_ID = b.SITE_ID 
                                        AND a.PARENT_ITEM_ID = b.ITEM_ID 
                                        AND isnull(b.IS_VALID, 'Y') = 'Y' 
                                        AND isnull(b.EARLY_PRODUCING_TERM, 0) > 0 
                                  INNER JOIN dbo.TH_MST_ITEM  AS c
                                        ON  a.MASTER_ID = c.MASTER_ID 
                                        AND a.PLAN_ID = c.PLAN_ID 
                                        AND a.CHILD_ITEM_ID = c.ITEM_ID 
                                        AND c.ITEM_TYPE != 'R'
                            WHERE a.MASTER_ID = @v_master_id 
                            AND   a.PLAN_ID = @v_plan_id 
                            AND   isnull(a.IS_VALID, 'Y') = 'Y'
                            GROUP BY a.CHILD_ITEM_ID, a.SITE_ID
                          )  AS b 
                ON  a.ITEM_ID = b.item_id 
                AND a.TO_SITE_ID = b.SITE_ID 
          LEFT OUTER JOIN (
                            SELECT 
                                  a.ITEM_ID, b.TO_SITE_ID, max(isnull(a.IS_PRIORITY, 'Y')) AS is_priority
                            FROM  dbo.TH_MST_ITEM_BOD  AS a
                                  INNER JOIN dbo.TH_MST_BOD  AS b
                                        ON  a.MASTER_ID = b.MASTER_ID 
                                        AND a.PLAN_ID = b.PLAN_ID 
                                        AND a.BOD_ID = b.BOD_ID 
                            WHERE a.MASTER_ID = @v_master_id 
                            AND   a.PLAN_ID = @v_plan_id
                            GROUP BY a.ITEM_ID, b.TO_SITE_ID
                          )  AS d 
                ON  a.ITEM_ID = d.ITEM_ID 
                AND a.TO_SITE_ID = d.TO_SITE_ID 
          LEFT OUTER JOIN (
                            SELECT 
                                  a.SITE_ID, min(c.ITEM_TYPE) AS item_type, min(b.IS_FINITE) AS expr, max(b.IS_FINITE) AS expr$2
                            FROM  dbo.TH_ENG_OP_RES_GROUP_MAP  AS a
                                  INNER JOIN dbo.TH_ENG_RESOURCE  AS b
                                        ON  a.MASTER_ID = b.MASTER_ID 
                                        AND a.PLAN_ID = b.PLAN_ID 
                                        AND a.RESOURCE_GROUP_ID = b.RESOURCE_GROUP_ID 
                                  INNER JOIN dbo.TH_ENG_ITEM  AS c
                                        ON  a.MASTER_ID = c.MASTER_ID 
                                        AND a.PLAN_ID = c.PLAN_ID 
                                        AND a.ITEM_ID = c.ITEM_ID 
                            WHERE a.MASTER_ID = @v_master_id 
                            AND   a.PLAN_ID = @v_plan_id
                            GROUP BY a.SITE_ID
                            HAVING min(b.IS_FINITE) = max(b.IS_FINITE) 
                            AND    min(b.IS_FINITE) = 'N'
                          )  AS c 
                ON a.TO_SITE_ID = c.SITE_ID

         --LOG 생성
       EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_ITEM_BOD', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_ITEM_BOD_CAL
           (
            MASTER_ID, 
            PLAN_ID, 
            ITEM_ID, 
            BOD_ID, 
            ALT_PRIORITY, 
            ALT_RATE, 
            START_DTTM, 
            END_DTTM, 
            TRANSFER_LOT_SIZE, 
            IS_PREV_LOT_SIZE, 
            IS_PULL, 
            PRE_BUFFER_TIME, 
            POST_BUFFER_TIME, 
            BUFFER_TIME_UOM, 
            IS_USE, 
            ROUTE_SELECTOR_ID, 
            SAFETY_STOCK_TERM, 
            SAFETY_STOCK_TERM_UOM, 
            SAFETY_STOCK_QTY, 
            DESCR, 
            EARLY_PRODUCING_TERM, 
            EARLY_PRODUCING_TERM_UOM
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.ITEM_ID, 
            a.BOD_ID, 
            a.ALT_PRIORITY, 
            CASE isnull(b.is_priority, 'Y')
            WHEN 'N' THEN a.ALT_RATE ELSE 0 END AS alt_rate, 
            a.start_dttm, 
            a.end_dttm, 
            a.transfer_lot_size, 
            a.IS_PREV_LOT_SIZE, 
            a.IS_PULL, 
            a.PRE_BUFFER_TIME, 
            a.POST_BUFFER_TIME, 
            a.BUFFER_TIME_UOM, 
            a.IS_USE, 
            NULL AS route_selector_id, 
            NULL AS safety_stock_term, 
            NULL AS safety_stock_term_uom, 
            NULL AS safety_stock_qty, 
            NULL AS descr, 
            a.EARLY_PRODUCING_TERM, 
            a.EARLY_PRODUCING_TERM_UOM
      FROM 
          (
            SELECT 
                  a.MASTER_ID, 
                  a.PLAN_ID, 
                  a.ITEM_ID, 
                  a.BOD_ID, 
                  b.TO_SITE_ID, 
                  a.ALT_PRIORITY, 
                  a.ALT_RATE, 
                  a.START_DATE AS start_dttm, 
                  a.END_DATE AS end_dttm, 
                  a.TRANSPORT_LOT_SIZE AS transfer_lot_size, 
                  a.IS_PREV_LOT_SIZE, 
                  a.IS_PULL, 
                  a.PRE_BUFFER_TIME, 
                  a.POST_BUFFER_TIME, 
                  a.BUFFER_TIME_UOM, 
                  a.IS_USE, 
                  NULL AS route_selector_id, 
                  NULL AS descr, 
                  NULL AS safety_stock_term, 
                  NULL AS safety_stock_term_uom, 
                  NULL AS safety_stock_qty, 
                  a.EARLY_PRODUCING_TERM, 
                  a.EARLY_PRODUCING_TERM_UOM
            FROM  dbo.TH_MST_ITEM_BOD_CAL  AS a
                  INNER JOIN dbo.TH_MST_BOD  AS b
                        ON  a.MASTER_ID = b.MASTER_ID 
                        AND a.PLAN_ID = b.PLAN_ID 
                        AND a.BOD_ID = b.BOD_ID  
            WHERE a.MASTER_ID = @v_master_id 
            AND   a.PLAN_ID = @v_plan_id
          ) AS a 
          LEFT OUTER JOIN (
                            SELECT 
                                  a.ITEM_ID, b.TO_SITE_ID, max(isnull(a.IS_PRIORITY, 'Y')) AS is_priority
                            FROM  dbo.TH_MST_ITEM_BOD  AS a
                                  INNER JOIN dbo.TH_MST_BOD  AS b
                                        ON  a.MASTER_ID = b.MASTER_ID 
                                        AND a.PLAN_ID = b.PLAN_ID 
                                        AND a.BOD_ID = b.BOD_ID 
                            WHERE a.MASTER_ID = @v_master_id 
                            AND   a.PLAN_ID = @v_plan_id
                            GROUP BY a.ITEM_ID, b.TO_SITE_ID
                          )  AS b 
                ON  a.ITEM_ID = b.ITEM_ID 
                AND a.TO_SITE_ID = b.TO_SITE_ID

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_ITEM_BOD_CAL', 'INSERT', @@ROWCOUNT, null, null, null 

      INSERT INTO dbo.TH_ENG_BOD_PATTERN
           (
            MASTER_ID, 
            PLAN_ID, 
            BOD_PATTERN_ID, 
            CYCLE_TIME, 
            CYCLE_TIME_UOM, 
            DESCR
           )
      SELECT 
            a.MASTER_ID, 
            a.PLAN_ID, 
            a.BOD_PATTERN_ID, 
            a.CYCLE_TIME, 
            a.CYCLE_TIME_UOM, 
            a.DESCR
      FROM  dbo.TH_MST_BOD_PATTERN  AS a
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_BOD_PATTERN', 'INSERT', @@ROWCOUNT, null, null, null


      INSERT INTO dbo.TH_ENG_BATCH_INFO
           (
            MASTER_ID,
            PLAN_ID,
            BATCH_RES_GROUP_ID,
            BATCH_GROUP_ID,
            ITEM_ID,
            MAX_BATCH_QTY,
            BATCH_TIME,
            BATCH_TIME_UOM,
            PREFER_RATIO,
            WAIT_TOLERANCE_TIME,
            WAIT_TOLERANCE_TIME_UOM,
            DESCR
           )
      SELECT DISTINCT
            a.MASTER_ID,
            a.PLAN_ID,
            a.BATCH_RES_GROUP_ID,
            a.SITE_ID + '::' + a.BATCH_GROUP_ID AS BATCH_GROUP_ID,    -- SITE 마다 BATCH 가 다르기 때문에 여기에 한다.
            a.ITEM_ID,
            a.MAX_BATCH_QTY,
            a.BATCH_TIME,
            a.BATCH_TIME_UOM,
            a.PREFER_RATIO,
            a.WAIT_TOLERANCE_TIME,
            a.WAIT_TOLERANCE_TIME_UOM,
            a.SITE_ID AS DESCR            
      FROM  dbo.TH_MST_BATCH_INFO  AS a
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_BATCH_INFO', 'INSERT', @@ROWCOUNT, null, null, null

      INSERT INTO dbo.TH_ENG_BATCH_INFO_CAL
           (
            MASTER_ID,
            PLAN_ID,
            BATCH_RES_GROUP_ID,
            BATCH_GROUP_ID,
            ITEM_ID,
            START_DTTM,
            END_DTTM,
            MAX_BATCH_QTY,
            BATCH_TIME,
            BATCH_TIME_UOM,
            PREFER_RATIO,
            WAIT_TOLERANCE_TIME,
            WAIT_TOLERANCE_TIME_UOM,
            DESCR
           )
      SELECT 
            a.MASTER_ID,
            a.PLAN_ID,
            a.BATCH_RES_GROUP_ID,
            a.BATCH_GROUP_ID,
            a.ITEM_ID,
            a.START_DTTM,
            a.END_DTTM,
            a.MAX_BATCH_QTY,
            a.BATCH_TIME,
            a.BATCH_TIME_UOM,
            a.PREFER_RATIO,
            a.WAIT_TOLERANCE_TIME,
            a.WAIT_TOLERANCE_TIME_UOM,
            a.SITE_ID AS DESCR
      FROM  dbo.TH_MST_BATCH_INFO_CAL  AS a
      WHERE a.MASTER_ID = @v_master_id 
      AND   a.PLAN_ID = @v_plan_id

      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_ENG_BATCH_INFO_CAL', 'INSERT', @@ROWCOUNT, null, null, null

      ----------------------------------------------------------------------------
      ----------------------------------------------------------------------------
      ----------------------------------------------------------------------------
      ----------------------------------------------------------------------------
      ----------------------------------------------------------------------------

      EXECUTE dbo.PR_SCM_MF_ENG_AMEND_COPY   @v_master_id, @v_plan_id
       
      ----------------------------------------------------------------------------
      -- 특화기능 적용 부분

      -- LANE 의 경우 TH_MST 를 기준으로 데이터를 생성하므로 맨 첫번째에 실행되어야 한다.
      EXECUTE dbo.PR_SCM_MF_LANE_ROUTE_ENG    @v_master_id, @v_plan_id

      EXECUTE dbo.PR_SCM_MF_BATCH_ROUTE_ENG   @v_master_id, @v_plan_id

      IF CHARINDEX('E_POST', @v_master_id) > 0
        BEGIN

          EXEC PR_SCM_MF_EPOST_BOM @v_master_id, @v_plan_id
        
        END
      ELSE
        BEGIN

            EXECUTE dbo.PR_SCM_MF_MULTI_ROUTE_ENG   @v_master_id, @v_plan_id

            EXECUTE dbo.PR_SCM_MF_MULTI_OPERATION_ENG   @v_master_id, @v_plan_id
        END

      EXECUTE dbo.PR_SCM_MF_SITE_ROUTE_ENG   @v_master_id, @v_plan_id

      EXECUTE dbo.PR_SCM_MF_STOCK_SITE_ENG   @v_master_id, @v_plan_id   -- 주석처리

      ----------------------------------------------------------------------------
          
      /* -- ###  INSTANCE별 PREFER 수행  ### */
      IF @v_plan_type = 'PRE'
      BEGIN
      
        IF CHARINDEX('E_PRE', @v_master_id) > 0
          EXECUTE PR_SCM_MF_PREFER_TACT_SETUP_WEEK  @v_master_id, @v_plan_id, 'E2000', '-';
        --ELSE IF CHARINDEX('E_POST', @v_master_id) > 0
        --  EXECUTE PR_SCM_MF_PREFER_TACT_SETUP_WEEK  @v_master_id, @v_plan_id, 'E4000', '-';
        ELSE IF CHARINDEX('CELL', @v_master_id) > 0
          EXECUTE PR_SCM_MF_PREFER_TACT_SETUP_WEEK  @v_master_id, @v_plan_id, 'A9000', 'A4000';
        ELSE IF CHARINDEX('PACK', @v_master_id) > 0
          EXECUTE PR_SCM_MF_PREFER_TACT_SETUP_WEEK  @v_master_id, @v_plan_id, 'P9500', 'P5500';
        ELSE IF CHARINDEX('SRS', @v_master_id) > 0
          EXECUTE PR_SCM_MF_PREFER_TACT_SETUP_WEEK  @v_master_id, @v_plan_id, 'S2000', '-';
        --ELSE IF CHARINDEX('E_PMIX', @v_master_id) > 0
        --  EXECUTE PR_SCM_MF_PREFER_TACT_SETUP_WEEK  @v_master_id, @v_plan_id, 'E0500', '-';

      END

      -- 최종 보완 모델링 부분 처리
      EXECUTE dbo.PR_SCM_MF_FINAL             @v_master_id, @v_plan_id

      -- BOM EFF_START_DATE, EFF_END_DATE 반영
      EXECUTE dbo.PR_SCM_MF_BOM_EFFECTIVE     @v_master_id, @v_plan_id
        
      ----------------------------------------------------------------------------
      -- out 결과 삭제
      EXECUTE dbo.PR_SCM_MF_OUT_DELETE        @v_master_id, @v_plan_id

      
     SELECT @v_flag =  ENGINE_FLAG
     FROM SY_FP_PLAN_STATUS_H AS a
         WHERE 
            a.INSTANCE_ID = @v_master_id AND 
            a.PLAN_ID = @v_plan_id
            
         -- UI에서 STOP을 했을경우 체크하여 ENGINE실행 안되도록 FLAG UPDATE
         IF  @v_flag = 'S'
           BEGIN
             UPDATE dbo.TH_MST_ENG_PLAN_FLAG
                SET 
                   INBOUND_FLAG = 'C', 
                   INBOUND_END = sysdatetime(), 
                   ENGINE_FLAG = 'S',
                   UPDATE_ID = @v_proc_name, 
                   UPDATE_DATE = sysdatetime()
             FROM dbo.TH_MST_ENG_PLAN_FLAG  AS a
             WHERE 
                a.MASTER_ID = @v_master_id AND 
                a.PLAN_ID = @v_plan_id AND 
                a.OUT_VERSION_ID = @v_plan_id
                
             UPDATE SY_FP_PLAN_STATUS_H
                SET 
                   ACTIVE_FLAG = 0,
                   INBOUND_FLAG = 'C',
                   INBOUND_STEP = '4',
                   INBOUND_END = sysdatetime(), 
                   UPDATE_ID = @v_proc_name, 
                   UPDATE_TIME = sysdatetime()
             FROM SY_FP_PLAN_STATUS_H  AS a
             WHERE 
                a.INSTANCE_ID = @v_master_id AND 
                a.PLAN_ID = @v_plan_id
          END
       ELSE
         BEGIN
             UPDATE dbo.TH_MST_ENG_PLAN_FLAG
                SET 
                   INBOUND_FLAG = 'C', 
                   INBOUND_END = sysdatetime(), 
                   UPDATE_ID = @v_proc_name, 
                   UPDATE_DATE = sysdatetime()
             FROM dbo.TH_MST_ENG_PLAN_FLAG  AS a
             WHERE 
                a.MASTER_ID = @v_master_id AND 
                a.PLAN_ID = @v_plan_id AND 
                a.OUT_VERSION_ID = @v_plan_id
                
             UPDATE SY_FP_PLAN_STATUS_H
                SET 
                   INBOUND_FLAG = 'C',
                   INBOUND_STEP = '4',
                   INBOUND_END = sysdatetime(), 
                   UPDATE_ID = @v_proc_name, 
                   UPDATE_TIME = sysdatetime()
             FROM SY_FP_PLAN_STATUS_H  AS a
             WHERE 
                a.INSTANCE_ID = @v_master_id AND 
                a.PLAN_ID = @v_plan_id
        END
            
       --LOG 생성
       EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_MST_ENG_PLAN_FLAG', 'UPDATE', @@ROWCOUNT, null, null, null 
     
         --LOG 생성
         EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, null, 'END', null, null, '=============== End of procedure ===============', null
      END TRY

      BEGIN CATCH
         BEGIN

            DECLARE 
               @v_error_message nvarchar(max),
               @v_error_procedure nvarchar(max),
               @v_error_line nvarchar(max)

            SET @v_error_message = ERROR_MESSAGE()

            SET @v_error_procedure = ERROR_PROCEDURE()

            SET @v_error_line = convert(nvarchar,ERROR_LINE())

            EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_error_procedure, null, 'ERROR', null, @v_error_line, null, @v_error_message

            IF @@TRANCOUNT > 0
               COMMIT WORK 
         END
      END CATCH      
END
